def search_linkedin_users(query, limit=None, cursor=None, external_account_id=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    TOOL = "search_linkedin_users"
    XAC_RE = re.compile(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$")

    # --------- helpers ---------
    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _b64j(obj):
        raw = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _unb64j(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _normalize_query(q):
        return " ".join(q.strip().split()).lower()

    def _fingerprint(tool_name, params, extacct_id):
        norm = json.dumps({"tool": tool_name, "params": params, "external_account_id": extacct_id}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _pick_context(external_account_id_required, provider_allow):
        tenants = _load("tenants.json")
        api_keys = _load("api_keys.json")
        xacs = _load("external_accounts.json")

        # Allowed tenants: active and have at least one active external account matching
        candidates = []
        for t in tenants:
            if t.get("status") != "active":
                continue
            # must have at least one active key OR allow internal/system calls; here, tools have no explicit credential
            # so accept internal calls (api_key_id null). Still need a tenant context: pick one that can serve request.
            # Choose tenant with active matching external account.
            for xa in xacs:
                if xa.get("tenant_id") != t.get("id"):
                    continue
                if xa.get("status") != "active":
                    continue
                if xa.get("provider") not in provider_allow:
                    continue
                # external_account_id param, when provided, must match a record id OR match pattern and exist as id.
                candidates.append((t, xa))
        # If caller provided explicit external_account_id, require matching record id and pattern.
        if external_account_id_required is not None:
            xa_match = None
            for (t, xa) in candidates:
                if xa.get("id") == external_account_id_required:
                    xa_match = (t, xa)
                    break
            if xa_match is None:
                return None, None
            return xa_match

        # If not provided, resolve default per provider: must be is_default_for_provider==true for some allowed provider.
        for (t, xa) in candidates:
            if xa.get("is_default_for_provider") is True:
                return t, xa
        # else any active matching external account
        if candidates:
            return candidates[0][0], candidates[0][1]
        return None, None

    def _record_invocation(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    def _transition(inv_row, new_status, invocations):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = inv_row.get("status")
        if new_status not in allowed.get(cur, set()):
            return False
        inv_row["status"] = new_status
        inv_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_invocations.json", invocations)
        return True

    def _fail(inv_row, invocations, code, message, http_status=None):
        # Move to failed from queued or running via running
        if inv_row.get("status") == "queued":
            _transition(inv_row, "running", invocations)
        inv_row["error_code"] = code
        inv_row["error_message"] = message
        inv_row["http_status"] = http_status
        inv_row["response_payload"] = None
        _transition(inv_row, "failed", invocations)

    def _succeed(inv_row, invocations, payload, http_status=200, cache_hit=False, cache_ttl_seconds=0, upstream_latency_ms=None):
        if inv_row.get("status") == "queued":
            _transition(inv_row, "running", invocations)
        inv_row["response_payload"] = payload
        inv_row["http_status"] = http_status
        inv_row["cache_hit"] = bool(cache_hit)
        inv_row["cache_ttl_seconds"] = int(cache_ttl_seconds or 0)
        inv_row["upstream_latency_ms"] = upstream_latency_ms
        inv_row["error_code"] = None
        inv_row["error_message"] = None
        _transition(inv_row, "succeeded", invocations)

    def _enforce_quota(tenant_row, cost_estimate):
        # must be active already checked in context picker; still validate quota
        if tenant_row.get("status") != "active":
            return False, "Tenant is not active"
        mrl = tenant_row.get("monthly_request_limit", 0)
        mru = tenant_row.get("monthly_request_used", 0)
        if not isinstance(mrl, int) or not isinstance(mru, int):
            return False, "Tenant quota fields invalid"
        if mrl != 0 and mru >= mrl:
            return False, "Monthly request quota exceeded"
        mcl = tenant_row.get("monthly_cost_usd_limit", 0)
        mcu = tenant_row.get("monthly_cost_usd_used", 0)
        try:
            mcln = float(mcl)
            mcun = float(mcu)
        except Exception:
            return False, "Tenant cost quota fields invalid"
        if mcln != 0 and (mcun + float(cost_estimate)) > mcln + 1e-9:
            return False, "Monthly cost quota exceeded"
        return True, None

    def _apply_success_usage(tenants, tenant_row, cost_estimate):
        # atomically update in-memory then save tenants.json
        tenant_row["monthly_request_used"] = int(tenant_row.get("monthly_request_used", 0)) + 1
        tenant_row["monthly_cost_usd_used"] = float(tenant_row.get("monthly_cost_usd_used", 0.0)) + float(cost_estimate)
        tenant_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tenants.json", tenants)

    def _upsert_entities(entities, tenant_id, rows, source_invocation_id):
        changed = False
        by_key = {}
        for e in entities:
            k = (e.get("tenant_id"), e.get("entity_type"), e.get("linkedin_urn"))
            if k[2] is not None:
                by_key[k] = e
        for r in rows:
            urn = r.get("linkedin_urn")
            if not urn:
                continue
            k = (tenant_id, "user_profile", urn)
            existing = by_key.get(k)
            obs = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            status = "active"
            if isinstance(r.get("raw_payload"), dict) and r["raw_payload"].get("unavailable") is True:
                status = "stale"
            if existing:
                existing["public_url"] = r.get("public_url")
                existing["email"] = r.get("email")
                existing["display_name"] = r.get("display_name")
                existing["company_linkedin_urn"] = r.get("company_linkedin_urn")
                existing["raw_payload"] = r.get("raw_payload") if isinstance(r.get("raw_payload"), dict) else {}
                existing["source_invocation_id"] = source_invocation_id
                # transition allowed between active/stale
                if existing.get("status") in ("active", "stale") and status != existing.get("status"):
                    existing["status"] = status
                existing["observed_at"] = obs
                existing["updated_at"] = obs
                changed = True
            else:
                entities.append({
                    "id": _new_id("hdw_le"),
                    "tenant_id": tenant_id,
                    "entity_type": "user_profile",
                    "linkedin_urn": urn,
                    "public_url": r.get("public_url"),
                    "email": r.get("email"),
                    "display_name": r.get("display_name"),
                    "company_linkedin_urn": r.get("company_linkedin_urn"),
                    "raw_payload": r.get("raw_payload") if isinstance(r.get("raw_payload"), dict) else {},
                    "source_invocation_id": source_invocation_id,
                    "status": status,
                    "observed_at": obs,
                    "created_at": obs,
                    "updated_at": obs,
                })
                changed = True
        if changed:
            _save("linkedin_entities.json", entities)

    # --------- validate inputs ---------
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")
    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")
    if cursor is not None:
        c = _unb64j(cursor)
        if not isinstance(c, dict) or "offset" not in c or not isinstance(c.get("offset"), int) or c.get("offset") < 0:
            return _err("VALIDATION_ERROR", "cursor is malformed")
    if external_account_id is not None:
        if not isinstance(external_account_id, str) or not XAC_RE.match(external_account_id):
            return _err("VALIDATION_ERROR", "external_account_id is malformed", field="external_account_id")

    # --------- resolve auth/tenant/external account ---------
    tenant, xac = _pick_context(external_account_id, provider_allow={"linkedin", "linkedin_sales_navigator"})
    if tenant is None or xac is None:
        return _err("UNAUTHORIZED", "No accessible active external account available for this request")

    # --------- create invocation (queued) ---------
    invocations = _load("tool_invocations.json")
    inv_id = _new_id("hdw_inv")
    req_params = {"query": query, "limit": limit, "cursor": cursor, "external_account_id": external_account_id}
    req_fp = _fingerprint(TOOL, {"query": _normalize_query(query), "limit": limit, "cursor": cursor}, xac.get("id"))
    inv_row = {
        "id": inv_id,
        "tenant_id": tenant.get("id"),
        "api_key_id": None,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": req_fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    _record_invocation(invocations, inv_row)

    # --------- quota before running ---------
    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if t.get("id") == tenant.get("id")), None)
    ok, qmsg = _enforce_quota(tenant_row or {}, inv_row["cost_usd_estimate"])
    if not ok:
        _fail(inv_row, invocations, "QUOTA_EXCEEDED", qmsg)
        return _err("QUOTA_EXCEEDED", qmsg)

    if not _transition(inv_row, "running", invocations):
        _fail(inv_row, invocations, "INVALID_TRANSITION", "Invocation status transition not permitted")
        return _err("INVALID_TRANSITION", "Invocation status transition not permitted")

    # --------- "upstream" search via local cache ---------
    entities = _load("linkedin_entities.json")
    nq = _normalize_query(query)

    # filter active/stale only; exclude deleted/redacted from search results
    matches = []
    for e in entities:
        if e.get("tenant_id") != tenant_row.get("id"):
            continue
        if e.get("entity_type") != "user_profile":
            continue
        if e.get("status") not in ("active", "stale"):
            continue
        name = (e.get("display_name") or "").lower()
        urn = (e.get("linkedin_urn") or "").lower()
        pub = (e.get("public_url") or "").lower()
        email = (e.get("email") or "").lower()
        raw = e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {}
        headline = (raw.get("headline") or "")
        if isinstance(headline, str):
            headline = headline.lower()
        hay = " ".join([name, urn, pub, email, headline])
        if nq in hay:
            matches.append(e)

    # deterministic sort
    matches.sort(key=lambda r: ((r.get("display_name") or "").lower(), (r.get("linkedin_urn") or "")))

    offset = 0
    if cursor is not None:
        offset = _unb64j(cursor).get("offset", 0)

    page = matches[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(matches)
    next_cursor = _b64j({"offset": next_offset}) if has_more else None

    results = []
    for e in page:
        results.append({
            "linkedin_urn": e.get("linkedin_urn"),
            "public_url": e.get("public_url"),
            "display_name": e.get("display_name"),
            "company_linkedin_urn": e.get("company_linkedin_urn"),
            "status": e.get("status"),
        })

    payload = {"results": results, "total": len(matches), "limit": limit, "cursor": next_cursor, "has_more": has_more}

    _succeed(inv_row, invocations, payload, http_status=200, cache_hit=False, cache_ttl_seconds=0, upstream_latency_ms=int((time.time() - t0) * 1000))
    _apply_success_usage(tenants, tenant_row, inv_row["cost_usd_estimate"])

    # Upsert observed entities for read tool: mark observed now for returned profiles
    up_rows = []
    for e in page:
        up_rows.append({
            "linkedin_urn": e.get("linkedin_urn"),
            "public_url": e.get("public_url"),
            "email": e.get("email"),
            "display_name": e.get("display_name"),
            "company_linkedin_urn": e.get("company_linkedin_urn"),
            "raw_payload": e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {},
        })
    _upsert_entities(entities, tenant_row.get("id"), up_rows, inv_id)

    return payload

def get_linkedin_profile(linkedin_urn=None, public_url=None, external_account_id=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, secrets, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "get_linkedin_profile"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # ---- validate inputs (relaxed to match vendor surface behavior) ----
    if linkedin_urn is not None and not isinstance(linkedin_urn, str):
        return _err("VALIDATION_ERROR", "linkedin_urn must be a string", field="linkedin_urn")
    if public_url is not None and not isinstance(public_url, str):
        return _err("VALIDATION_ERROR", "public_url must be a string", field="public_url")
    if external_account_id is not None and not isinstance(external_account_id, str):
        return _err("VALIDATION_ERROR", "external_account_id must be a string", field="external_account_id")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")
    refresh = bool(refresh) if refresh is not None else False

    if (linkedin_urn is None or str(linkedin_urn).strip() == "") and (public_url is None or str(public_url).strip() == ""):
        return _err("VALIDATION_ERROR", "Either linkedin_urn or public_url must be provided.")
    linkedin_urn = linkedin_urn.strip() if isinstance(linkedin_urn, str) else None
    public_url = public_url.strip() if isinstance(public_url, str) else None

    # Accept many LinkedIn URNs; real service supports more than "fsd_profile".
    # Only reject if clearly not a URN when supplied.
    if linkedin_urn is not None:
        if not linkedin_urn.startswith("urn:li:"):
            return _err("VALIDATION_ERROR", "linkedin_urn must start with 'urn:li:'", field="linkedin_urn")

    if public_url is not None:
        try:
            pu = urllib.parse.urlparse(public_url)
            if not pu.scheme or not pu.netloc:
                return _err("VALIDATION_ERROR", "public_url is malformed", field="public_url")
        except Exception:
            return _err("VALIDATION_ERROR", "public_url is malformed", field="public_url")

    # external_account_id in schema is hdw_xac_..., but audit shows callers pass provider ids like urn:li:member:...
    # Real backend typically allows "environment" resolution; so treat unknown formats as "not an HDW external account id".
    xac_id = None
    if external_account_id is not None:
        if re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
            xac_id = external_account_id
        else:
            xac_id = None  # ignore and resolve default

    # ---- helpers ----
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{s}"

    def _fingerprint(tool_name, params, extacct_id):
        norm = json.dumps(
            {"tool_name": tool_name, "params": params, "external_account_id": extacct_id},
            sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _resolve_context(tenants, api_keys, external_accounts, requested_xac_id):
        # Pick a working tenant/external_account combo. If requested_xac_id provided, it must exist+active.
        # Else use provider default for linkedin/linkedin_sales_navigator; if none default, any active.
        providers = ("linkedin", "linkedin_sales_navigator", "linkedin_management")
        active_tenants = [t for t in tenants if t.get("status") == "active"]
        if requested_xac_id:
            for ea in external_accounts:
                if ea.get("id") == requested_xac_id and ea.get("status") == "active" and ea.get("provider") in providers:
                    t = next((tt for tt in active_tenants if tt.get("id") == ea.get("tenant_id")), None)
                    if t:
                        # choose an active key if available
                        k = next((kk for kk in api_keys if kk.get("tenant_id") == t.get("id") and kk.get("status") == "active"), None)
                        return t, k, ea
            return None, None, None

        # default first (rule)
        for t in active_tenants:
            tid = t.get("id")
            defaults = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers and ea.get("is_default_for_provider") is True]
            if defaults:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, defaults[0]

        # any active account
        for t in active_tenants:
            tid = t.get("id")
            eas = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers]
            if eas:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, eas[0]

        return None, None, None

    def _transition(inv, new_status):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = inv.get("status")
        if new_status not in allowed.get(cur, set()):
            return False
        inv["status"] = new_status
        inv["updated_at"] = now
        return True

    def _upsert_entity(entities, tenant_id, entity_type, linkedin_urn_value, public_url_value, payload, source_inv_id, status_value):
        # unique by (tenant_id, entity_type, linkedin_urn) if urn not null; else allow insert with url as hint
        existing = None
        if linkedin_urn_value:
            for e in entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == entity_type and e.get("linkedin_urn") == linkedin_urn_value:
                    existing = e
                    break
        if existing is None and public_url_value:
            for e in entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == entity_type and e.get("public_url") == public_url_value:
                    existing = e
                    break
        if existing is None:
            existing = {
                "id": _gen_id("hdw_li"),
                "tenant_id": tenant_id,
                "entity_type": entity_type,
                "linkedin_urn": linkedin_urn_value,
                "public_url": public_url_value,
                "email": None,
                "display_name": payload.get("display_name") if isinstance(payload, dict) else None,
                "company_linkedin_urn": payload.get("company_linkedin_urn") if isinstance(payload, dict) else None,
                "raw_payload": payload if isinstance(payload, dict) else {"data": payload},
                "source_invocation_id": source_inv_id,
                "status": status_value,
                "observed_at": now,
                "created_at": now,
                "updated_at": now,
            }
            entities.append(existing)
        else:
            existing["linkedin_urn"] = existing.get("linkedin_urn") or linkedin_urn_value
            existing["public_url"] = existing.get("public_url") or public_url_value
            existing["display_name"] = payload.get("display_name") if isinstance(payload, dict) else existing.get("display_name")
            existing["company_linkedin_urn"] = payload.get("company_linkedin_urn") if isinstance(payload, dict) else existing.get("company_linkedin_urn")
            existing["raw_payload"] = payload if isinstance(payload, dict) else {"data": payload}
            existing["source_invocation_id"] = source_inv_id
            existing["status"] = status_value
            existing["observed_at"] = now
            existing["updated_at"] = now
        return existing

    # ---- load store ----
    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    tool_invocations = _load("tool_invocations.json")
    linkedin_entities = _load("linkedin_entities.json")

    tenant, api_key_row, xac = _resolve_context(tenants, api_keys, external_accounts, xac_id)
    if tenant is None or xac is None:
        # must still write invocation audit (best-effort; no tenant means UNAUTHORIZED)
        return _err("UNAUTHORIZED", "No accessible tenant/external account context for LinkedIn provider.")

    tenant_id = tenant.get("id")
    api_key_id = api_key_row.get("id") if api_key_row else None

    # ---- create invocation row (queued) ----
    req_params = {"linkedin_urn": linkedin_urn, "public_url": public_url, "refresh": refresh}
    inv_id = _gen_id("hdw_inv")
    fp = _fingerprint(TOOL, req_params, xac.get("id"))
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    tool_invocations.append(inv)
    _save("tool_invocations.json", tool_invocations)

    # ---- auth rule for "environment default" accounts ----
    # If caller did not provide an hdw_xac id, we are using default; ensure default flag exists and active.
    if xac_id is None:
        if not (xac.get("is_default_for_provider") is True and xac.get("status") == "active"):
            _transition(inv, "running")  # queued->running then fail is what backend logs show
            inv["error_code"] = "AUTH_FAILED"
            inv["error_message"] = "No active default external account for provider 'linkedin'."
            _transition(inv, "failed")
            _save("tool_invocations.json", tool_invocations)
            return _err("UNAUTHORIZED", inv["error_message"])

    # ---- quota enforcement before running ----
    if tenant.get("status") != "active":
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant is not active; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    cost = float(inv.get("cost_usd_estimate", 0.0) or 0.0)
    if (isinstance(mrl, int) and mrl != 0 and isinstance(mru, int) and mru >= mrl) or (isinstance(mcl, (int, float)) and mcl != 0 and (float(mcu or 0.0) + cost) > float(mcl)):
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant quota exceeded; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    if not _transition(inv, "running"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    # ---- serve from cache if allowed and not refresh (for profile tool, cache is via linkedin_entities) ----
    cache_entity = None
    if not refresh:
        if linkedin_urn:
            for e in linkedin_entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "user_profile" and e.get("linkedin_urn") == linkedin_urn and e.get("status") in ("active", "stale", "redacted"):
                    cache_entity = e
                    break
        if cache_entity is None and public_url:
            for e in linkedin_entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "user_profile" and e.get("public_url") == public_url and e.get("status") in ("active", "stale", "redacted"):
                    cache_entity = e
                    break

    if cache_entity is not None:
        inv["cache_hit"] = True
        inv["http_status"] = 200
        inv["response_payload"] = cache_entity.get("raw_payload")
        # success transition + usage increment
        if not _transition(inv, "succeeded"):
            inv["error_code"] = "INVALID_TRANSITION"
            inv["error_message"] = "Illegal invocation status transition."
            _save("tool_invocations.json", tool_invocations)
            return _err("INVALID_TRANSITION", inv["error_message"])
        # increment tenant usage atomically with succeeded
        for t in tenants:
            if t.get("id") == tenant_id:
                t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
                t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used") or 0.0) + cost
                t["updated_at"] = now
                break
        if api_key_row:
            for k in api_keys:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
        _save("tenants.json", tenants)
        _save("api_keys.json", api_keys)
        _save("tool_invocations.json", tool_invocations)
        return {"data": inv["response_payload"], "invocation_id": inv_id, "cache_hit": True}

    # ---- "upstream fetch" simulated by normalizing any existing entity or creating minimal payload ----
    # Real backend would call LinkedIn; offline, we return best-known info if present else minimal resolution.
    payload = None
    # if requesting by public_url, try map to existing company/user payloads; else create minimal
    if linkedin_urn:
        existing = next((e for e in linkedin_entities if e.get("tenant_id") == tenant_id and e.get("entity_type") == "user_profile" and e.get("linkedin_urn") == linkedin_urn), None)
        payload = existing.get("raw_payload") if existing else {"linkedin_urn": linkedin_urn, "public_url": public_url}
    else:
        existing = next((e for e in linkedin_entities if e.get("tenant_id") == tenant_id and e.get("entity_type") == "user_profile" and e.get("public_url") == public_url), None)
        payload = existing.get("raw_payload") if existing else {"public_url": public_url, "linkedin_urn": None}

    # upsert entity (rule)
    status_value = "active"
    if isinstance(payload, dict) and payload.get("unavailable") is True:
        status_value = "stale"
    ent = _upsert_entity(linkedin_entities, tenant_id, "user_profile", linkedin_urn, public_url, payload, inv_id, status_value)
    _save("linkedin_entities.json", linkedin_entities)

    inv["http_status"] = 200
    inv["response_payload"] = ent.get("raw_payload")

    if not _transition(inv, "succeeded"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used") or 0.0) + cost
            t["updated_at"] = now
            break
    if api_key_row:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break

    _save("tenants.json", tenants)
    _save("api_keys.json", api_keys)
    _save("tool_invocations.json", tool_invocations)

    inv["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = now
    _save("tool_invocations.json", tool_invocations)
    return {"data": inv["response_payload"], "invocation_id": inv_id, "cache_hit": False}

def get_linkedin_email_user(email, external_account_id=None, refresh=None, **_extra):
