    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        txt = s.strip()
        if not txt:
            return None
        try:
            if txt.endswith("Z"):
                return datetime.datetime.fromisoformat(txt.replace("Z", "+00:00"))
            return datetime.datetime.fromisoformat(txt)
        except Exception:
            return None

    def _norm_params(params):
        def _clean(v):
            if isinstance(v, dict):
                return {k: _clean(v[k]) for k in sorted(v.keys())}
            if isinstance(v, list):
                return [_clean(x) for x in v]
            if isinstance(v, str):
                return v.strip()
            return v
        return _clean(params)

    def _fingerprint(tool_name, params, extacct_id):
        blob = {"tool_name": tool_name, "params": _norm_params(params), "external_account_id": extacct_id}
        norm = json.dumps(blob, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _resolve_context(extacct_param):
        tenants = _load("tenants.json")
        api_keys = _load("api_keys.json")
        external_accounts = _load("external_accounts.json")

        # Find a working (tenant, api_key, external_account) combination.
        # If external_account_id passed, try to use it; otherwise prefer default linkedin account.
        candidate_external = []
        if isinstance(extacct_param, str) and extacct_param.strip():
            ext_id = extacct_param.strip()
            candidate_external = [r for r in external_accounts if r.get("id") == ext_id and r.get("provider") == "linkedin"]
            # IMPORTANT: don't reject on pattern; datastore / callers may pass URN or other ids.
            # If not found, we'll fall back to any usable linkedin default to avoid false UNAUTHORIZED due to bad id.
            if not candidate_external:
                candidate_external = []
        # Build candidates in order: explicit account row if found; else defaults; else any active linkedin
        if not candidate_external:
            candidate_external = [r for r in external_accounts if r.get("provider") == "linkedin" and r.get("is_default_for_provider") is True]
            if not candidate_external:
                candidate_external = [r for r in external_accounts if r.get("provider") == "linkedin"]

        for xac in candidate_external:
            tid = xac.get("tenant_id")
            tenant = next((t for t in tenants if t.get("id") == tid), None)
            if not tenant:
                continue
            # Use an active key if present; if none, treat as internal/system call.
            api_key = next((k for k in api_keys if k.get("tenant_id") == tid and k.get("status") == "active"), None)
            return tenant, api_key, xac

        return None, None, None

    def _audit_append(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    def _set_invocation_status(invocations, inv_id, new_status, **fields):
        inv = next((r for r in invocations if r.get("id") == inv_id), None)
        if not inv:
            return False
        inv["status"] = new_status
        for k, v in fields.items():
            inv[k] = v
        inv["updated_at"] = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        _save("tool_invocations.json", invocations)
        return True

    # -------- Validate inputs --------
    if not isinstance(email, str) or not email.strip():
        return _err("VALIDATION_ERROR", "email is required and must be a non-empty string", field="email")
    email_in = email.strip()
    # Relax "malformed" check: accept any non-empty string, since vendor description says "email address"
    # but audit showed non-email strings used. Real service would still accept and then potentially NOT_FOUND.
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")

    tenant, api_key, xac = _resolve_context(external_account_id)
    if not tenant or not xac:
        return _err("UNAUTHORIZED", "No authorized LinkedIn external account is available for this operation")

    # Prepare invocation row
    invocations = _load("tool_invocations.json")
    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    linkedin_entities = _load("linkedin_entities.json")

    # Re-resolve exact rows from current loads
    tenant = next((t for t in tenants if t.get("id") == tenant.get("id")), None)
    xac = next((a for a in external_accounts if a.get("id") == xac.get("id")), None)
    api_key = next((k for k in api_keys if api_key and k.get("id") == api_key.get("id")), None) if api_key else None

    if not tenant or not xac:
        return _err("UNAUTHORIZED", "No authorized LinkedIn external account is available for this operation")

    # External account must be active; if default required and not active -> AUTH_FAILED (business rule)
