            "status": "queued",
            "request_params": params,
            "request_fingerprint": fp,
            "response_payload": None,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "cache_hit": False,
            "cache_ttl_seconds": 0,
            "upstream_latency_ms": None,
            "cost_usd_estimate": 0.0,
            "created_at": now,
            "updated_at": now,
        }
        _audit_append(invocations, row)
        _set_invocation_status(invocations, inv_id, "running")
        _set_invocation_status(invocations, inv_id, "failed", error_code="AUTH_FAILED", error_message="LinkedIn external account is not active; re-authentication or re-enable required.")
        return _err("UNAUTHORIZED", "External account not active for provider linkedin", error_code="AUTH_FAILED")

    # Validate api_key constraints if present
    if api_key is not None:
        if api_key.get("status") != "active" or api_key.get("tenant_id") != tenant.get("id"):
            return _err("UNAUTHORIZED", "API key is not active for this tenant")

    # Build request fingerprint and caching policy (this tool is not declared cacheable; cache via linkedin_entities instead)
    params = {"email": email_in, "external_account_id": external_account_id, "refresh": bool(refresh) if refresh is not None else False}
    fp = _fingerprint(TOOL, params, xac.get("id"))

    inv_id = _gen_id("hdw_inv")
    inv_row = {
        "id": inv_id,
        "tenant_id": tenant.get("id"),
        "api_key_id": api_key.get("id") if api_key else None,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
