        "created_at": now,
        "updated_at": now,
    }
    _audit_append(invocations, inv_row)

    # queued -> running gate with quota checks (before moving to running)
    if tenant.get("status") != "active":
        _set_invocation_status(invocations, inv_id, "failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active; request rejected before execution.")
        return _err("QUOTA_EXCEEDED", "Tenant is not active; request rejected before execution.", error_code="QUOTA_EXCEEDED")

    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    cost_est = 0.0
    if isinstance(mrl, int) and mrl != 0 and isinstance(mru, int) and mru >= mrl:
        _set_invocation_status(invocations, inv_id, "failed", error_code="QUOTA_EXCEEDED", error_message="Tenant request quota exceeded; request rejected before execution.")
        return _err("QUOTA_EXCEEDED", "Tenant request quota exceeded; request rejected before execution.", error_code="QUOTA_EXCEEDED")
    if isinstance(mcl, (int, float)) and float(mcl) != 0.0 and (float(mcu) + cost_est) > float(mcl):
        _set_invocation_status(invocations, inv_id, "failed", error_code="QUOTA_EXCEEDED", error_message="Tenant cost quota exceeded; request rejected before execution.")
        return _err("QUOTA_EXCEEDED", "Tenant cost quota exceeded; request rejected before execution.", error_code="QUOTA_EXCEEDED")

    _set_invocation_status(invocations, inv_id, "running")

    # "Cache" behaviour for this tool: return from normalized linkedin_entities if exists and refresh != True
    cache_hit = False
    if not params["refresh"]:
        cached = next((e for e in linkedin_entities
                       if e.get("tenant_id") == tenant.get("id")
                       and e.get("entity_type") == "user_profile"
                       and e.get("email") == email_in
                       and e.get("status") in ("active", "stale", "redacted")), None)
        if cached and isinstance(cached.get("raw_payload"), dict):
            payload = cached.get("raw_payload")
            cache_hit = True
            _set_invocation_status(invocations, inv_id, "succeeded", response_payload=payload, http_status=200, cache_hit=True, cost_usd_estimate=0.0)
            # success increments usage (rule) even for cache-served? Rule says "On invocation success, increment ...".
            # Apply it.
            tenant_row = next((t for t in tenants if t.get("id") == tenant.get("id")), None)
            if tenant_row:
                if isinstance(tenant_row.get("monthly_request_used"), int):
                    tenant_row["monthly_request_used"] = tenant_row.get("monthly_request_used", 0) + 1
                if isinstance(tenant_row.get("monthly_cost_usd_used"), (int, float)):
                    tenant_row["monthly_cost_usd_used"] = float(tenant_row.get("monthly_cost_usd_used", 0.0)) + 0.0
                tenant_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
                _save("tenants.json", tenants)
            if api_key is not None:
                api_key["last_used_at"] = now
                api_key["updated_at"] = now
                _save("api_keys.json", api_keys)
            return {"data": payload, "invocation_id": inv_id, "cache_hit": True}

    # No upstream available offline: real behaviour in this datastore-backed server is to resolve only if previously known.
    # If not present, treat as NOT_FOUND and mark invocation failed.
    _set_invocation_status(invocations, inv_id, "failed", error_code="NOT_FOUND", error_message="Email could not be resolved to a LinkedIn user in cached store.")
    if api_key is not None:
        api_key["last_used_at"] = now
        api_key["updated_at"] = now
        _save("api_keys.json", api_keys)
    return _err("NOT_FOUND", "Email could not be resolved to a LinkedIn user.")

def get_linkedin_user_posts(linkedin_urn, limit=None, cursor=None, external_account_id=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    TOOL = "get_linkedin_user_posts"
    XAC_RE = re.compile(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _b64j(obj):
        raw = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _unb64j(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _fingerprint(tool_name, params, extacct_id):
        norm = json.dumps({"tool": tool_name, "params": params, "external_account_id": extacct_id}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _pick_context(external_account_id_required, provider_allow):
        tenants = _load("tenants.json")
        xacs = _load("external_accounts.json")
        candidates = []
        for t in tenants:
            if t.get("status") != "active":
                continue
            for xa in xacs:
                if xa.get("tenant_id") != t.get("id"):
                    continue
                if xa.get("status") != "active":
                    continue
                if xa.get("provider") not in provider_allow:
                    continue
                candidates.append((t, xa))
        if external_account_id_required is not None:
            for t, xa in candidates:
                if xa.get("id") == external_account_id_required:
                    return t, xa
            return None, None
        for t, xa in candidates:
            if xa.get("is_default_for_provider") is True:
                return t, xa
        return candidates[0] if candidates else (None, None)

    def _record_invocation(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    def _transition(inv_row, new_status, invocations):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = inv_row.get("status")
        if new_status not in allowed.get(cur, set()):
            return False
        inv_row["status"] = new_status
        inv_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_invocations.json", invocations)
        return True

    def _fail(inv_row, invocations, code, message, http_status=None):
        if inv_row.get("status") == "queued":
            _transition(inv_row, "running", invocations)
        inv_row["error_code"] = code
        inv_row["error_message"] = message
        inv_row["http_status"] = http_status
        inv_row["response_payload"] = None
        _transition(inv_row, "failed", invocations)

    def _succeed(inv_row, invocations, payload, http_status=200, cache_hit=False, cache_ttl_seconds=0, upstream_latency_ms=None):
        if inv_row.get("status") == "queued":
            _transition(inv_row, "running", invocations)
        inv_row["response_payload"] = payload
        inv_row["http_status"] = http_status
        inv_row["cache_hit"] = bool(cache_hit)
        inv_row["cache_ttl_seconds"] = int(cache_ttl_seconds or 0)
        inv_row["upstream_latency_ms"] = upstream_latency_ms
        inv_row["error_code"] = None
        inv_row["error_message"] = None
        _transition(inv_row, "succeeded", invocations)

    def _enforce_quota(tenant_row, cost_estimate):
        if tenant_row.get("status") != "active":
            return False, "Tenant is not active"
        mrl = tenant_row.get("monthly_request_limit", 0)
        mru = tenant_row.get("monthly_request_used", 0)
        if not isinstance(mrl, int) or not isinstance(mru, int):
            return False, "Tenant quota fields invalid"
        if mrl != 0 and mru >= mrl:
            return False, "Monthly request quota exceeded"
        mcl = tenant_row.get("monthly_cost_usd_limit", 0)
        mcu = tenant_row.get("monthly_cost_usd_used", 0)
        try:
            mcln = float(mcl)
            mcun = float(mcu)
        except Exception:
            return False, "Tenant cost quota fields invalid"
        if mcln != 0 and (mcun + float(cost_estimate)) > mcln + 1e-9:
            return False, "Monthly cost quota exceeded"
        return True, None

    def _apply_success_usage(tenants, tenant_row, cost_estimate):
        tenant_row["monthly_request_used"] = int(tenant_row.get("monthly_request_used", 0)) + 1
        tenant_row["monthly_cost_usd_used"] = float(tenant_row.get("monthly_cost_usd_used", 0.0)) + float(cost_estimate)
        tenant_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tenants.json", tenants)

    def _upsert_posts(entities, tenant_id, post_entities, source_invocation_id):
        # Minimal upsert for posts
        obs = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        changed = False
        for p in post_entities:
            urn = p.get("linkedin_urn")
            if not urn:
                continue
            existing = None
            for e in entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "post" and e.get("linkedin_urn") == urn:
                    existing = e
                    break
            status = "active"
            raw = p.get("raw_payload") if isinstance(p.get("raw_payload"), dict) else {}
            if raw.get("unavailable") is True:
                status = "stale"
            if existing:
                existing["public_url"] = p.get("public_url") or existing.get("public_url")
                existing["display_name"] = p.get("display_name") or existing.get("display_name")
                existing["raw_payload"] = raw
                existing["source_invocation_id"] = source_invocation_id
                if existing.get("status") in ("active", "stale") and status != existing.get("status"):
                    existing["status"] = status
                existing["observed_at"] = obs
                existing["updated_at"] = obs
                changed = True
            else:
                entities.append({
                    "id": _new_id("hdw_le"),
                    "tenant_id": tenant_id,
                    "entity_type": "post",
                    "linkedin_urn": urn,
                    "public_url": p.get("public_url"),
                    "email": None,
                    "display_name": p.get("display_name"),
                    "company_linkedin_urn": None,
                    "raw_payload": raw,
                    "source_invocation_id": source_invocation_id,
                    "status": status,
                    "observed_at": obs,
                    "created_at": obs,
                    "updated_at": obs,
                })
                changed = True
        if changed:
            _save("linkedin_entities.json", entities)

    # --------- validate inputs ---------
    if not isinstance(linkedin_urn, str) or not linkedin_urn.strip():
        return _err("VALIDATION_ERROR", "linkedin_urn is required and must be a non-empty string")
    if ":" not in linkedin_urn or not re.match(r"^[a-zA-Z0-9_]+:.+$", linkedin_urn):
        return _err("VALIDATION_ERROR", "linkedin_urn is malformed or missing required prefix", field="linkedin_urn")

    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")

    if cursor is not None:
        c = _unb64j(cursor)
        if not isinstance(c, dict) or "offset" not in c or not isinstance(c.get("offset"), int) or c.get("offset") < 0:
            return _err("VALIDATION_ERROR", "cursor is malformed")

    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    if external_account_id is not None:
        if not isinstance(external_account_id, str) or not XAC_RE.match(external_account_id):
            return _err("VALIDATION_ERROR", "external_account_id is malformed", field="external_account_id")

    # --------- resolve auth/tenant/external account ---------
    tenant, xac = _pick_context(external_account_id, provider_allow={"linkedin"})
    if tenant is None or xac is None:
        return _err("UNAUTHORIZED", "No accessible active external account available for this request")

    # --------- create invocation (queued) ---------
    invocations = _load("tool_invocations.json")
    inv_id = _new_id("hdw_inv")
    req_params = {"linkedin_urn": linkedin_urn, "limit": limit, "cursor": cursor, "external_account_id": external_account_id, "refresh": refresh}
    req_fp = _fingerprint(TOOL, {"linkedin_urn": linkedin_urn, "limit": limit, "cursor": cursor, "refresh": refresh}, xac.get("id"))
    inv_row = {
        "id": inv_id,
        "tenant_id": tenant.get("id"),
        "api_key_id": None,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": req_fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    _record_invocation(invocations, inv_row)

    tenants = _load("tenants.json")
    tenant_row = next((t for t in tenants if t.get("id") == tenant.get("id")), None)
    ok, qmsg = _enforce_quota(tenant_row or {}, inv_row["cost_usd_estimate"])
    if not ok:
        _fail(inv_row, invocations, "QUOTA_EXCEEDED", qmsg)
        return _err("QUOTA_EXCEEDED", qmsg)

    if not _transition(inv_row, "running", invocations):
        _fail(inv_row, invocations, "INVALID_TRANSITION", "Invocation status transition not permitted")
        return _err("INVALID_TRANSITION", "Invocation status transition not permitted")

    entities = _load("linkedin_entities.json")

    # Offline behavior: can only return posts already cached for this tenant and user.
    # We associate posts to the user via raw_payload.author_urn or raw_payload.owner_urn.
    cached_posts = []
    if not refresh:
        for e in entities:
            if e.get("tenant_id") != tenant_row.get("id"):
                continue
            if e.get("entity_type") != "post":
                continue
            if e.get("status") not in ("active", "stale"):
                continue
            raw = e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {}
            author = raw.get("author_urn") or raw.get("owner_urn")
            if author == linkedin_urn:
                cached_posts.append(e)

    # Sort by observed_at/updated_at descending if present
    def _dt_key(v):
        s = v.get("observed_at") or v.get("updated_at") or ""
        return s
    cached_posts.sort(key=_dt_key, reverse=True)

    offset = 0
    if cursor is not None:
        offset = _unb64j(cursor).get("offset", 0)

    page = cached_posts[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(cached_posts)
    next_cursor = _b64j({"offset": next_offset}) if has_more else None

    results = []
    for e in page:
        results.append({
            "linkedin_urn": e.get("linkedin_urn"),
            "public_url": e.get("public_url"),
            "text": (e.get("raw_payload") or {}).get("text") if isinstance(e.get("raw_payload"), dict) else None,
            "created_time": (e.get("raw_payload") or {}).get("created_time") if isinstance(e.get("raw_payload"), dict) else None,
            "status": e.get("status"),
        })

    payload = {"results": results, "total": len(cached_posts), "limit": limit, "cursor": next_cursor, "has_more": has_more}

    # Upsert observed_at now for returned posts
    up_posts = []
    for e in page:
        up_posts.append({
            "linkedin_urn": e.get("linkedin_urn"),
            "public_url": e.get("public_url"),
            "display_name": e.get("display_name"),
            "raw_payload": e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {},
        })
    _upsert_posts(entities, tenant_row.get("id"), up_posts, inv_id)

    _succeed(inv_row, invocations, payload, http_status=200, cache_hit=not refresh, cache_ttl_seconds=0, upstream_latency_ms=int((time.time() - t0) * 1000))
    _apply_success_usage(tenants, tenant_row, inv_row["cost_usd_estimate"])
    return payload

def get_linkedin_user_reactions(linkedin_urn, limit=None, cursor=None, external_account_id=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "get_linkedin_user_reactions"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if not isinstance(linkedin_urn, str) or linkedin_urn.strip() == "":
        return _err("VALIDATION_ERROR", "linkedin_urn is required and must be a non-empty string.", field="linkedin_urn")
    linkedin_urn = linkedin_urn.strip()
    # Relax URN validation: accept any LinkedIn URN (activity/member/fsd_profile/etc).
    if not linkedin_urn.startswith("urn:li:"):
        return _err("VALIDATION_ERROR", "linkedin_urn must start with 'urn:li:'", field="linkedin_urn")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")
    refresh = bool(refresh) if refresh is not None else False

    xac_id = None
    if external_account_id is not None:
        if not isinstance(external_account_id, str):
            return _err("VALIDATION_ERROR", "external_account_id must be a string", field="external_account_id")
        if re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
            xac_id = external_account_id
        else:
            xac_id = None  # ignore non-hdw ids

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{s}"

    def _fingerprint(tool_name, params, extacct_id):
        norm = json.dumps({"tool_name": tool_name, "params": params, "external_account_id": extacct_id},
                          sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _b64e(off):
        raw = json.dumps({"v": 1, "offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset = 0
    if cursor is not None:
        offset = _b64d(cursor)
        if offset is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    def _resolve_context(tenants, api_keys, external_accounts, requested_xac_id):
        providers = ("linkedin",)
        active_tenants = [t for t in tenants if t.get("status") == "active"]
        if requested_xac_id:
            for ea in external_accounts:
                if ea.get("id") == requested_xac_id and ea.get("status") == "active" and ea.get("provider") in providers:
                    t = next((tt for tt in active_tenants if tt.get("id") == ea.get("tenant_id")), None)
                    if t:
                        k = next((kk for kk in api_keys if kk.get("tenant_id") == t.get("id") and kk.get("status") == "active"), None)
                        return t, k, ea
            return None, None, None
        for t in active_tenants:
            tid = t.get("id")
            defaults = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers and ea.get("is_default_for_provider") is True]
            if defaults:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, defaults[0]
        for t in active_tenants:
            tid = t.get("id")
            eas = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers]
            if eas:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, eas[0]
        return None, None, None

    def _transition(inv, new_status):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = inv.get("status")
        if new_status not in allowed.get(cur, set()):
            return False
        inv["status"] = new_status
        inv["updated_at"] = now
        return True

    def _upsert_entity(entities, tenant_id, entity_type, urn, payload, source_inv_id, status_value="active"):
        existing = None
        if urn:
            for e in entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == entity_type and e.get("linkedin_urn") == urn:
                    existing = e
                    break
        if existing is None:
            existing = {
                "id": _gen_id("hdw_li"),
                "tenant_id": tenant_id,
                "entity_type": entity_type,
                "linkedin_urn": urn,
                "public_url": None,
                "email": None,
                "display_name": payload.get("display_name") if isinstance(payload, dict) else None,
                "company_linkedin_urn": payload.get("company_linkedin_urn") if isinstance(payload, dict) else None,
                "raw_payload": payload if isinstance(payload, dict) else {"data": payload},
                "source_invocation_id": source_inv_id,
                "status": status_value,
                "observed_at": now,
                "created_at": now,
                "updated_at": now,
            }
            entities.append(existing)
        else:
            existing["raw_payload"] = payload if isinstance(payload, dict) else {"data": payload}
            existing["source_invocation_id"] = source_inv_id
            existing["status"] = status_value
            existing["observed_at"] = now
            existing["updated_at"] = now
        return existing

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    tool_invocations = _load("tool_invocations.json")
    linkedin_entities = _load("linkedin_entities.json")

    tenant, api_key_row, xac = _resolve_context(tenants, api_keys, external_accounts, xac_id)
    if tenant is None or xac is None:
        return _err("UNAUTHORIZED", "No accessible tenant/external account context for LinkedIn provider.")

    tenant_id = tenant.get("id")
    api_key_id = api_key_row.get("id") if api_key_row else None

    req_params = {"linkedin_urn": linkedin_urn, "limit": limit, "cursor": cursor, "refresh": refresh}
    inv_id = _gen_id("hdw_inv")
    fp = _fingerprint(TOOL, req_params, xac.get("id"))
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    tool_invocations.append(inv)
    _save("tool_invocations.json", tool_invocations)

    if xac_id is None:
        if not (xac.get("is_default_for_provider") is True and xac.get("status") == "active"):
            _transition(inv, "running")
            inv["error_code"] = "AUTH_FAILED"
            inv["error_message"] = "No active default external account for provider 'linkedin'."
            _transition(inv, "failed")
            _save("tool_invocations.json", tool_invocations)
            return _err("UNAUTHORIZED", inv["error_message"])

    # quota
    if tenant.get("status") != "active":
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant is not active; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    cost = float(inv.get("cost_usd_estimate", 0.0) or 0.0)
    if (isinstance(mrl, int) and mrl != 0 and isinstance(mru, int) and mru >= mrl) or (isinstance(mcl, (int, float)) and mcl != 0 and (float(mcu or 0.0) + cost) > float(mcl)):
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant quota exceeded; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    if not _transition(inv, "running"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    # offline listing: use reaction entities already stored, else return empty list
    # We'll treat entity_type='reaction' with company_linkedin_urn or raw_payload.actor_urn matching linkedin_urn
    reactions = []
    for e in linkedin_entities:
        if e.get("tenant_id") != tenant_id or e.get("entity_type") != "reaction":
            continue
        rp = e.get("raw_payload")
        actor = None
        if isinstance(rp, dict):
            actor = rp.get("actor_urn") or rp.get("actor") or rp.get("user_urn")
        if actor == linkedin_urn:
            reactions.append(e)

    # deterministic order
    def _sort_key(e):
        dt = None
        rp = e.get("raw_payload")
        if isinstance(rp, dict):
            dt = rp.get("created_at") or rp.get("time") or rp.get("timestamp")
        pdt = None
        if isinstance(dt, str):
            try:
                if dt.endswith("Z"):
                    pdt = datetime.datetime.fromisoformat(dt[:-1] + "+00:00")
                else:
                    pdt = datetime.datetime.fromisoformat(dt)
            except Exception:
                pdt = None
        return (pdt is None, pdt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), e.get("id") or "")

    reactions.sort(key=_sort_key, reverse=True)
    total = len(reactions)
    page = reactions[offset: offset + limit]
    next_offset = offset + len(page)
    next_cursor = _b64e(next_offset) if next_offset < total else None

    # Upsert observed entities (rule) for returned page
    for e in page:
        # refresh observed_at + updated_at
        e["observed_at"] = now
        if e.get("updated_at", "") < now:
            e["updated_at"] = now
        if e.get("status") not in ("active", "stale", "redacted", "deleted"):
            e["status"] = "active"
    _save("linkedin_entities.json", linkedin_entities)

    inv["http_status"] = 200
    inv["response_payload"] = {
        "items": [p.get("raw_payload") for p in page],
        "next_cursor": next_cursor,
        "has_more": next_cursor is not None,
        "total": total,
    }

    if not _transition(inv, "succeeded"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used") or 0.0) + cost
            t["updated_at"] = now
            break
    if api_key_row:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break

    _save("tenants.json", tenants)
    _save("api_keys.json", api_keys)
    inv["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = now
    _save("tool_invocations.json", tool_invocations)

    return {"data": inv["response_payload"], "invocation_id": inv_id, "cache_hit": False}

def get_linkedin_chat_messages(conversation_id, limit=None, cursor=None, external_account_id=None, refresh=None, **_extra):
