        if not re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
            return _err("VALIDATION_ERROR", "external_account_id is malformed.")

    def _b64e(o):
        raw = json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
