    if external_account_id is not None:
        for ea in external_accounts:
            if ea.get("id") == external_account_id:
                if ea.get("provider") != "linkedin_management":
                    return _err("VALIDATION_ERROR", "external_account_id must reference a linkedin_management provider external account.")
                ext = ea
                break
        if ext is None:
            return _err("VALIDATION_ERROR", "external_account_id is invalid (not found).")
        for t in tenants:
            if t.get("id") == ext.get("tenant_id"):
                tenant = t
                break
        if tenant is None:
            return _err("UNAUTHORIZED", "No authorized tenant context found for provided external_account_id.")
    else:
        for t in _candidate_tenants():
            eas = [ea for ea in external_accounts
                   if ea.get("tenant_id") == t.get("id")
                   and ea.get("provider") == "linkedin_management"
                   and ea.get("is_default_for_provider") is True
                   and ea.get("status") == "active"]
            if eas:
                tenant = t
                ext = eas[0]
                break
        if tenant is None or ext is None:
            return _err("UNAUTHORIZED", "No default active linkedin_management external account is configured for any tenant.")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + now + str(time.time())).encode("utf-8")).digest()
        out = []
        for b in h[:16]:
            out.append(alphabet[b % len(alphabet)])
        return f"hdw_inv_{''.join(out)}"

    offset = 0
    if cursor:
        c = _b64d(cursor)
        if not isinstance(c, dict) or c.get("v") != 1 or c.get("tool") != "get_linkedin_chat_messages":
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        if c.get("conversation_id") != conversation_id:
            return _err("VALIDATION_ERROR", "cursor does not match request.")
        if not isinstance(c.get("offset"), int) or c.get("offset") < 0:
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        offset = c["offset"]

    request_params = {
        "conversation_id": conversation_id,
        "limit": limit,
        "cursor": cursor,
        "external_account_id": external_account_id,
        "refresh": refresh
    }

    fp_src = {
        "tool": "get_linkedin_chat_messages",
        "conversation_id": conversation_id,
        "limit": limit,
        "cursor_offset": offset,
        "provider": ext.get("provider") if ext else None,
        "external_account_id": ext.get("id") if ext else None
    }
    fp = hashlib.sha256(json.dumps(fp_src, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    inv_id = _new_id("get_linkedin_chat_messages")
    inv = {
        "id": inv_id,
        "tenant_id": tenant.get("id") if tenant else None,
        "api_key_id": None,
        "external_account_id": ext.get("id") if ext else None,
        "tool_name": "get_linkedin_chat_messages",
        "status": "queued",
        "request_params": request_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    def _update_inv(new_fields):
        nonlocal invocations, inv
        inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        inv.update(new_fields)
        for i, r in enumerate(invocations):
            if r.get("id") == inv["id"]:
                invocations[i] = inv
                break
        _save("tool_invocations.json", invocations)

    if ext.get("status") != "active":
        _update_inv({
            "status": "failed",
            "error_code": "AUTH_FAILED",
            "error_message": "External account is not active; reauthentication or enablement required."
        })
        return _err("UNAUTHORIZED", "External account authentication failed.", error_code="AUTH_FAILED", invocation_id=inv_id)

    if tenant.get("status") != "active":
        _update_inv({"status": "failed", "error_code": "QUOTA_EXCEEDED", "error_message": "Tenant is not active."})
        return _err("QUOTA_EXCEEDED", "Tenant is not active.", error_code="QUOTA_EXCEEDED", invocation_id=inv_id)

    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    if mrl != 0 and mru >= mrl:
        _update_inv({"status": "failed", "error_code": "QUOTA_EXCEEDED", "error_message": "Monthly request quota exceeded."})
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", error_code="QUOTA_EXCEEDED", invocation_id=inv_id)

    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    cost = float(inv.get("cost_usd_estimate", 0.0) or 0.0)
    if (mcl or 0) != 0 and (float(mcu or 0.0) + cost) > float(mcl):
        _update_inv({"status": "failed", "error_code": "QUOTA_EXCEEDED", "error_message": "Monthly cost quota exceeded."})
        return _err("QUOTA_EXCEEDED", "Monthly cost quota exceeded.", error_code="QUOTA_EXCEEDED", invocation_id=inv_id)

    _update_inv({"status": "running"})

    try:
        # Deterministic pseudo-upstream
        seed = int(hashlib.sha256((tenant["id"] + "|" + conversation_id).encode("utf-8")).hexdigest()[:8], 16)
        total = 53 + (seed % 97)  # 53..149
        start = offset
        end = min(offset + limit, total)

        msgs = []
        for idx in range(start, end):
            mid = hashlib.sha256((conversation_id + "|msg|" + str(idx)).encode("utf-8")).hexdigest()[:20]
            msg_urn = f"message:{mid}"
            payload = {
                "type": "message",
                "conversation_id": conversation_id,
                "message_urn": msg_urn,
                "text": f"Message {idx} in conversation {conversation_id}",
                "sender": {"urn": f"profile:{hashlib.sha256((conversation_id+'|sender|'+str(idx)).encode('utf-8')).hexdigest()[:12]}"},
                "sent_at_index": idx
            }
            msgs.append(payload)

        def _ent_id(entity_type, urn):
            h = hashlib.sha256((tenant["id"] + "|" + entity_type + "|" + (urn or "")).encode("utf-8")).hexdigest()[:18]
            return f"hdw_li_{h}"

        changed = False
        for p in msgs:
            urn = p.get("message_urn")
            existing = None
            for e in entities:
                if e.get("tenant_id") == tenant["id"] and e.get("entity_type") == "message" and e.get("linkedin_urn") == urn:
                    existing = e
                    break
            status = "active" if not p.get("unavailable") else "stale"
            if existing:
                existing["raw_payload"] = p
                existing["source_invocation_id"] = inv_id
                if existing.get("status") in ("active", "stale"):
                    existing["status"] = status
                existing["observed_at"] = now
                existing["updated_at"] = now
                changed = True
            else:
                entities.append({
                    "id": _ent_id("message", urn),
                    "tenant_id": tenant["id"],
                    "entity_type": "message",
                    "linkedin_urn": urn,
                    "public_url": None,
                    "email": None,
                    "display_name": None,
                    "company_linkedin_urn": None,
                    "raw_payload": p,
                    "source_invocation_id": inv_id,
                    "status": status,
                    "observed_at": now,
                    "created_at": now,
                    "updated_at": now
                })
                changed = True
        if changed:
            _save("linkedin_entities.json", entities)

        next_cursor = None
        has_more = end < total
        if has_more:
            next_cursor = _b64e({"v": 1, "tool": "get_linkedin_chat_messages", "conversation_id": conversation_id, "offset": end})

        response_payload = {
            "data": msgs,
            "paging": {"limit": limit, "cursor": next_cursor, "has_more": has_more, "total_estimate": total}
        }

        # Success accounting
        for i, t in enumerate(tenants):
            if t.get("id") == tenant["id"]:
                tenants[i] = t
                break
        tenant["monthly_request_used"] = int(tenant.get("monthly_request_used", 0)) + 1
        tenant["monthly_cost_usd_used"] = float(tenant.get("monthly_cost_usd_used", 0.0) or 0.0) + cost
        tenant["updated_at"] = now
        _save("tenants.json", tenants)

        _update_inv({
            "status": "succeeded",
            "response_payload": response_payload,
            "http_status": 200,
            "upstream_latency_ms": 0
        })

        return {
            "invocation_id": inv_id,
            "messages": msgs,
            "limit": limit,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total_estimate": total,
            "cache_hit": False,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    except Exception as e:
        _update_inv({"status": "failed", "error_code": "FAILED", "error_message": str(e), "http_status": 500})
        return _err("CONFLICT", "Invocation failed unexpectedly.", error_code="FAILED", invocation_id=inv_id)

