def send_linkedin_connection(linkedin_urn, message=None, external_account_id=None, **_extra):
    import json, os, datetime, time, re, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "send_linkedin_connection"
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    # Validate linkedin_urn: accept common LinkedIn user URNs AND fsd_profile style.
    if not isinstance(linkedin_urn, str) or not linkedin_urn.strip():
        return _err("VALIDATION_ERROR", "linkedin_urn is required and must be a non-empty string", field="linkedin_urn")
    linkedin_urn = linkedin_urn.strip()
    # Relaxed: allow fsd_profile:..., urn:li:member:..., urn:li:fsd_profile:..., urn:li:profile:...
    if not (re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*:[A-Za-z0-9\-_.=]+$", linkedin_urn) or re.match(r"^urn:li:[A-Za-z0-9_]+:[A-Za-z0-9\-_.=]+$", linkedin_urn)):
        return _err("VALIDATION_ERROR", "linkedin_urn is malformed; expected a LinkedIn user/profile URN (e.g., fsd_profile:... or urn:li:member:...)", field="linkedin_urn")

    if message is not None:
        if not isinstance(message, str):
            return _err("VALIDATION_ERROR", "message must be a string", field="message")
        # keep upstream-ish constraint but not overly strict
        if len(message) > 300:
            return _err("VALIDATION_ERROR", "message exceeds upstream constraints (max 300 characters)", field="message")

    if external_account_id is not None and not isinstance(external_account_id, str):
        return _err("VALIDATION_ERROR", "external_account_id must be a string", field="external_account_id")
    requested_xac = None
    if isinstance(external_account_id, str) and re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
        requested_xac = external_account_id
    # if caller passes a provider URN, treat as omitted and use default

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    invocations = _load("tool_invocations.json")
    entities = _load("linkedin_entities.json")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    def _fingerprint(params, extacct_id):
        norm = json.dumps(
            {"tool_name": TOOL, "params": params, "external_account_id": extacct_id},
            sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _resolve_context():
        allowed_providers = {"linkedin", "linkedin_management"}
        for t in tenants:
            if t.get("status") != "active":
                continue
            tid = t.get("id")
            chosen = None
            if requested_xac:
                for ea in external_accounts:
                    if ea.get("id") == requested_xac and ea.get("tenant_id") == tid and ea.get("provider") in allowed_providers:
                        chosen = ea
                        break
                if chosen is None:
                    continue
            else:
                defaults = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("provider") in allowed_providers and ea.get("is_default_for_provider") is True]
                chosen = defaults[0] if defaults else None
                if chosen is None:
                    actives = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("provider") in allowed_providers]
                    chosen = actives[0] if actives else None
                if chosen is None:
                    continue

            if chosen.get("status") != "active":
                return t, None, chosen, "AUTH_FAILED", "LinkedIn external account is not active; re-auth required or disabled."

            ak = next((k for k in api_keys if k.get("tenant_id") == tid and k.get("status") == "active"), None)
            return t, ak, chosen, None, None
        return None, None, None, "UNAUTHORIZED", "No authorized tenant/context with a usable LinkedIn external account."

    tenant, api_key_row, ext_acct, ctx_err, ctx_msg = _resolve_context()

    inv_id = _gen_id("hdw_inv")
    req_params = {"linkedin_urn": linkedin_urn, "message": message, "external_account_id": external_account_id}
    fp = _fingerprint({"linkedin_urn": linkedin_urn, "message": message}, ext_acct.get("id") if ext_acct else (requested_xac or None))
    inv_row = {
        "id": inv_id,
        "tenant_id": tenant.get("id") if tenant else None,
        "api_key_id": api_key_row.get("id") if api_key_row else None,
        "external_account_id": ext_acct.get("id") if ext_acct else None,
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
