    if not isinstance(post_urn, str) or post_urn.strip() == "":
        return _err("VALIDATION_ERROR", "post_urn is required and must be a non-empty string.", field="post_urn")
    post_urn = post_urn.strip()
    # Relax: accept activity URN too (audit uses urn:li:activity:...)
    if not post_urn.startswith("urn:li:"):
        return _err("VALIDATION_ERROR", "post_urn must start with 'urn:li:'", field="post_urn")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _b64e(off):
        raw = json.dumps({"v": 1, "offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset = 0
    if cursor is not None:
        offset = _b64d(cursor)
        if offset is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{s}"

    def _fingerprint(tool_name, params, extacct_id):
        norm = json.dumps({"tool_name": tool_name, "params": params, "external_account_id": extacct_id},
                          sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _resolve_context(tenants, api_keys, external_accounts):
        providers = ("linkedin", "linkedin_management", "linkedin_sales_navigator")
        active_tenants = [t for t in tenants if t.get("status") == "active"]
        for t in active_tenants:
            tid = t.get("id")
            defaults = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers and ea.get("is_default_for_provider") is True]
            if defaults:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, defaults[0]
        for t in active_tenants:
            tid = t.get("id")
            eas = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers]
            if eas:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, eas[0]
        return None, None, None

    def _transition(inv, new_status):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = inv.get("status")
        if new_status not in allowed.get(cur, set()):
            return False
        inv["status"] = new_status
        inv["updated_at"] = now
        return True

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    tool_invocations = _load("tool_invocations.json")
    linkedin_entities = _load("linkedin_entities.json")

    tenant, api_key_row, xac = _resolve_context(tenants, api_keys, external_accounts)
    if tenant is None or xac is None or not (xac.get("is_default_for_provider") is True and xac.get("status") == "active"):
        return _err("UNAUTHORIZED", "No active default external account for provider 'linkedin'.")

    tenant_id = tenant.get("id")
    api_key_id = api_key_row.get("id") if api_key_row else None

    req_params = {"post_urn": post_urn, "limit": limit, "cursor": cursor}
    inv_id = _gen_id("hdw_inv")
    fp = _fingerprint(TOOL, req_params, xac.get("id"))
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    tool_invocations.append(inv)
    _save("tool_invocations.json", tool_invocations)

    # quota
    if tenant.get("status") != "active":
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant is not active; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    if isinstance(mrl, int) and mrl != 0 and isinstance(mru, int) and mru >= mrl:
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant quota exceeded; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    if not _transition(inv, "running"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    comments = []
    for e in linkedin_entities:
        if e.get("tenant_id") != tenant_id or e.get("entity_type") != "comment":
            continue
        rp = e.get("raw_payload")
        if isinstance(rp, dict) and (rp.get("post_urn") == post_urn or rp.get("parent_urn") == post_urn or rp.get("target_urn") == post_urn):
            comments.append(e)

    comments.sort(key=lambda e: (e.get("observed_at") or "", e.get("id") or ""), reverse=True)
    total = len(comments)
    page = comments[offset: offset + limit]
    next_offset = offset + len(page)
    next_cursor = _b64e(next_offset) if next_offset < total else None

    # upsert observed for returned (rule)
    for e in page:
        e["observed_at"] = now
        e["updated_at"] = now if (e.get("updated_at") or "") <= now else e.get("updated_at")
        if e.get("status") not in ("active", "stale", "redacted", "deleted"):
            e["status"] = "active"
    _save("linkedin_entities.json", linkedin_entities)

    inv["http_status"] = 200
    inv["response_payload"] = {"items": [p.get("raw_payload") for p in page], "next_cursor": next_cursor, "has_more": next_cursor is not None, "total": total}
    if not _transition(inv, "succeeded"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
            t["updated_at"] = now
            break
    if api_key_row:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break
    _save("tenants.json", tenants)
    _save("api_keys.json", api_keys)
    inv["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = now
    _save("tool_invocations.json", tool_invocations)
    return {"data": inv["response_payload"], "invocation_id": inv_id}

def get_linkedin_google_company(query, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if not q:
        return _err("VALIDATION_ERROR", "query must not be empty")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    invocations = _load("tool_invocations.json")
    entities = _load("linkedin_entities.json")

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _norm_params(obj):
        # Stable JSON normalization for fingerprinting
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _fp(tool_name, params, extacct_id):
        base = tool_name + "|" + _norm_params(params) + "|" + (extacct_id or "")
        return hashlib.sha256(base.encode("utf-8")).hexdigest()

    def _find_working_context():
        # Prefer tenants that are active and have an active google_search_api external account
        for t in tenants:
            if t.get("status") != "active":
                continue
            # Find external account for google
            cands = [ea for ea in external_accounts
                     if ea.get("tenant_id") == t.get("id")
                     and ea.get("provider") == "google_search_api"
                     and ea.get("status") == "active"
                     and ea.get("is_default_for_provider") is True]
            if not cands:
                continue
            # Any active API key for audit context (optional)
            k = None
            for ak in api_keys:
                if ak.get("tenant_id") == t.get("id") and ak.get("status") == "active":
                    k = ak
                    break
            return t, k, cands[0]
        return None, None, None

    tenant, api_key, ext_acct = _find_working_context()
    if not tenant or not ext_acct:
        # Must log the attempt as failed even if unauthorized context is missing? We can only log with tenant_id; no tenant => cannot.
        return _err("UNAUTHORIZED", "No active tenant/default Google external account available")

    tenant_id = tenant["id"]
    api_key_id = api_key["id"] if api_key else None
    external_account_id = ext_acct["id"]

    # Create invocation queued
    params = {"query": q}
    fingerprint = _fp("get_linkedin_google_company", params, external_account_id)
    inv_id = _gen_id("inv")
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": external_account_id,
        "tool_name": "get_linkedin_google_company",
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fingerprint,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 86400,  # 24h cache for this tool
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.002,  # small estimated cost per Google query
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    def _update_inv(status, **fields):
        nonlocal invocations
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = inv.get("status")
        if status != cur:
            if status not in allowed.get(cur, set()):
                inv["status"] = cur
                inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                inv["error_code"] = "INVALID_TRANSITION"
                inv["error_message"] = f"Illegal status transition {cur} -> {status}"
                _save("tool_invocations.json", invocations)
                return False, _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")
            inv["status"] = status
        for k, v in fields.items():
            inv[k] = v
        inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_invocations.json", invocations)
        return True, None

    # Quota enforcement before running
    if tenant.get("status") != "active":
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active")
        return _err("QUOTA_EXCEEDED", "Tenant is not active")
    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    cost = inv["cost_usd_estimate"]
    if (isinstance(mrl, int) and mrl != 0 and mru >= mrl) or (not isinstance(mrl, int)):
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")
    if (mcl != 0 and (mcu + cost) > mcl):
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly cost quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly cost quota exceeded")

    # Key validity if present
    if api_key_id is not None:
        akrow = next((x for x in api_keys if x.get("id") == api_key_id), None)
        if not akrow or akrow.get("status") != "active" or akrow.get("tenant_id") != tenant_id:
            _update_inv("failed", error_code="AUTH_FAILED", error_message="API key invalid for tenant")
            return _err("UNAUTHORIZED", "API key invalid for tenant")

    # Transition to running
    ok, e = _update_inv("running")
    if not ok:
        return e

    # Cache lookup within TTL: only succeeded, ttl>0, same tenant, within ttl window
    ttl = inv.get("cache_ttl_seconds", 0) or 0
    if ttl > 0:
        now_dt = datetime.datetime.utcnow().replace(microsecond=0)
        best = None
        for prior in invocations:
            if prior.get("tenant_id") != tenant_id:
                continue
            if prior.get("tool_name") != "get_linkedin_google_company":
                continue
            if prior.get("status") != "succeeded":
                continue
            if prior.get("cache_ttl_seconds", 0) <= 0:
                continue
            if prior.get("request_fingerprint") != fingerprint:
                continue
            ca = prior.get("created_at")
            try:
                created_dt = datetime.datetime.fromisoformat(ca.replace("Z", ""))
            except Exception:
                continue
            ttl_s = prior.get("cache_ttl_seconds", 0) or 0
            if ttl_s <= 0:
                continue
            if (now_dt - created_dt).total_seconds() <= ttl_s:
                best = prior
                break
        if best and isinstance(best.get("response_payload"), dict):
            # Serve from cache without incrementing quotas? Business rules increment on success; cached is still success.
            payload = best["response_payload"]
            # PII control for redacted entities: omit email and sensitive raw fields when serving from cache.
            # Here payload is google results; no email expected. Keep as-is.
            inv["cache_hit"] = True
            inv["response_payload"] = payload
            inv["http_status"] = 200
            # Commit success + quota increment atomically
            # Update tenant counters then invocation
            for t in tenants:
                if t.get("id") == tenant_id:
                    t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
                    t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used", 0.0)) + float(cost)
                    t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    break
            _save("tenants.json", tenants)
            _update_inv("succeeded")
            if api_key_id is not None:
                for k in api_keys:
                    if k.get("id") == api_key_id:
                        k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        k["updated_at"] = k["last_used_at"]
                        break
                _save("api_keys.json", api_keys)
            inv["upstream_latency_ms"] = 0
            _save("tool_invocations.json", invocations)
            return {
                "tool": "get_linkedin_google_company",
                "invocation_id": inv_id,
                "cache_hit": True,
                "results": payload.get("results", []),
                "top_result": payload.get("results", [None])[0] if payload.get("results") else None
            }

    # Simulate upstream Google search results deterministically (offline)
    upstream_start = time.time()
    slug = re.sub(r"\s+", "-", q.lower()).strip("-")
    company_id = hashlib.sha256(("company|" + q).encode("utf-8")).hexdigest()[:10]
    public_url = f"https://www.linkedin.com/company/{slug}/"
    linkedin_urn = f"urn:li:fsd_company:{company_id}"

    results = [
        {
            "rank": 1,
            "title": f"{q} | LinkedIn",
            "url": public_url,
            "snippet": f"View {q} on LinkedIn. See company info, employees, and more."
        },
        {
            "rank": 2,
            "title": f"{q} - Overview",
            "url": f"https://www.linkedin.com/company/{slug}/about/",
            "snippet": f"About {q} on LinkedIn."
        }
    ]
    upstream_ms = int((time.time() - upstream_start) * 1000)

    payload = {
        "query": q,
        "results": results,
        "best_match": {
            "company_urn": linkedin_urn,
            "public_url": public_url,
            "display_name": q
        }
    }

    inv["response_payload"] = payload
    inv["http_status"] = 200
    inv["upstream_latency_ms"] = upstream_ms

    # Upsert company entity (as discovery result)
    ent_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    existing = None
    for e in entities:
        if e.get("tenant_id") == tenant_id and e.get("entity_type") == "company" and e.get("linkedin_urn") == linkedin_urn:
            existing = e
            break
    if existing:
        # status transition to active if allowed
        curst = existing.get("status")
        if curst in ("deleted",):
            pass
        else:
            existing["public_url"] = public_url
            existing["display_name"] = q
            existing["raw_payload"] = {"discovered_via": "google", "google_results": results}
            existing["source_invocation_id"] = inv_id
            existing["status"] = "active" if curst in ("active", "stale") else curst
            existing["observed_at"] = ent_now
            existing["updated_at"] = ent_now
    else:
        entities.append({
            "id": _gen_id("li"),
            "tenant_id": tenant_id,
            "entity_type": "company",
            "linkedin_urn": linkedin_urn,
            "public_url": public_url,
            "email": None,
            "display_name": q,
            "company_linkedin_urn": None,
            "raw_payload": {"discovered_via": "google", "google_results": results},
            "source_invocation_id": inv_id,
            "status": "active",
            "observed_at": ent_now,
            "created_at": ent_now,
            "updated_at": ent_now
        })
    _save("linkedin_entities.json", entities)

    # Commit success + quota increment
    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used", 0.0)) + float(cost)
            t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("tenants.json", tenants)

    _update_inv("succeeded")
    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                k["updated_at"] = k["last_used_at"]
                break
        _save("api_keys.json", api_keys)

    inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    inv["upstream_latency_ms"] = upstream_ms
    _save("tool_invocations.json", invocations)

    return {
        "tool": "get_linkedin_google_company",
        "invocation_id": inv_id,
        "cache_hit": False,
        "results": results,
        "top_result": results[0] if results else None,
        "best_match": payload["best_match"]
    }

def get_linkedin_company(company_urn=None, public_url=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    t0 = time.time()

    # Validate inputs
    if company_urn is not None and not isinstance(company_urn, str):
        return _err("VALIDATION_ERROR", "company_urn must be a string")
    if public_url is not None and not isinstance(public_url, str):
        return _err("VALIDATION_ERROR", "public_url must be a string")
    cu = company_urn.strip() if isinstance(company_urn, str) else None
    pu = public_url.strip() if isinstance(public_url, str) else None
    if (not cu) and (not pu):
        return _err("VALIDATION_ERROR", "Either company_urn or public_url must be provided")

    def _is_company_urn(u):
        return bool(re.match(r"^urn:li:(fsd_company|company):[A-Za-z0-9]+$", u or ""))

    def _is_linkedin_company_url(u):
        return bool(re.match(r"^https?://([a-z]{2,3}\.)?www\.linkedin\.com/company/[^/\s]+/?", u or ""))

    if cu and not _is_company_urn(cu):
        return _err("VALIDATION_ERROR", "company_urn format is invalid")
    if pu and not _is_linkedin_company_url(pu):
        return _err("VALIDATION_ERROR", "public_url format is invalid")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    invocations = _load("tool_invocations.json")
    entities = _load("linkedin_entities.json")

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _norm_params(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _fp(tool_name, params, extacct_id):
        base = tool_name + "|" + _norm_params(params) + "|" + (extacct_id or "")
        return hashlib.sha256(base.encode("utf-8")).hexdigest()

    def _find_working_context():
        # Needs default LinkedIn provider account. Prefer linkedin_management then linkedin.
        providers = ["linkedin_management", "linkedin", "linkedin_sales_navigator"]
        for t in tenants:
            if t.get("status") != "active":
                continue
            for p in providers:
                cands = [ea for ea in external_accounts
                         if ea.get("tenant_id") == t.get("id")
                         and ea.get("provider") == p
                         and ea.get("is_default_for_provider") is True
                         and ea.get("status") == "active"]
                if not cands:
                    continue
                k = None
                for ak in api_keys:
                    if ak.get("tenant_id") == t.get("id") and ak.get("status") == "active":
                        k = ak
                        break
                return t, k, cands[0]
        return None, None, None

    tenant, api_key, ext_acct = _find_working_context()
    if not tenant or not ext_acct:
        return _err("UNAUTHORIZED", "No active tenant/default LinkedIn external account available")

    tenant_id = tenant["id"]
    api_key_id = api_key["id"] if api_key else None
    external_account_id = ext_acct["id"]

    params = {}
    if cu:
        params["company_urn"] = cu
    if pu:
        params["public_url"] = pu
    fingerprint = _fp("get_linkedin_company", params, external_account_id)

    inv_id = _gen_id("inv")
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": external_account_id,
        "tool_name": "get_linkedin_company",
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fingerprint,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    def _update_inv(status, **fields):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = inv.get("status")
        if status != cur:
            if status not in allowed.get(cur, set()):
                inv["error_code"] = "INVALID_TRANSITION"
                inv["error_message"] = f"Illegal status transition {cur} -> {status}"
                inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("tool_invocations.json", invocations)
                return False, _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")
            inv["status"] = status
        for k, v in fields.items():
            inv[k] = v
        inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_invocations.json", invocations)
        return True, None

    # Quota check (still required before running even if cost=0)
    if tenant.get("status") != "active":
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active")
        return _err("QUOTA_EXCEEDED", "Tenant is not active")
    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    if (isinstance(mrl, int) and mrl != 0 and mru >= mrl) or (not isinstance(mrl, int)):
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")

    if api_key_id is not None:
        akrow = next((x for x in api_keys if x.get("id") == api_key_id), None)
        if not akrow or akrow.get("status") != "active" or akrow.get("tenant_id") != tenant_id:
            _update_inv("failed", error_code="AUTH_FAILED", error_message="API key invalid for tenant")
            return _err("UNAUTHORIZED", "API key invalid for tenant")

    ok, e = _update_inv("running")
    if not ok:
        return e

    # Resolve company urn if only public_url given by looking into cache
    resolved_urn = cu
    if not resolved_urn and pu:
        cached = next((x for x in entities
                       if x.get("tenant_id") == tenant_id and x.get("entity_type") == "company"
                       and x.get("public_url") == pu and x.get("status") in ("active", "stale", "redacted")), None)
        if cached:
            resolved_urn = cached.get("linkedin_urn")

    if cu and pu:
        # If both provided, ensure they refer to same entity if possible
        cached_by_urn = next((x for x in entities
                              if x.get("tenant_id") == tenant_id and x.get("entity_type") == "company"
                              and x.get("linkedin_urn") == cu), None)
        if cached_by_urn and cached_by_urn.get("public_url") and cached_by_urn.get("public_url") != pu:
            _update_inv("failed", error_code="VALIDATION_ERROR", error_message="company_urn and public_url conflict")
            return _err("VALIDATION_ERROR", "company_urn and public_url conflict")

    # Create deterministic normalized company payload (offline)
    upstream_start = time.time()
    if not resolved_urn:
        # derive from url slug
        slug = pu.rstrip("/").split("/company/")[-1].split("/")[0] if pu else "company"
        cid = hashlib.sha256(("company|" + slug).encode("utf-8")).hexdigest()[:10]
        resolved_urn = f"urn:li:fsd_company:{cid}"
    if not pu:
        slug = resolved_urn.split(":")[-1]
        pu = f"https://www.linkedin.com/company/{slug}/"

    display = "Company " + resolved_urn.split(":")[-1]
    raw = {
        "urn": resolved_urn,
        "public_url": pu,
        "name": display,
        "about": f"Auto-generated company profile for {display}.",
        "website": None,
        "industry": None,
        "headcount_range": None
    }
    upstream_ms = int((time.time() - upstream_start) * 1000)

    # Upsert linkedin_entities company
    ent_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    existing = next((x for x in entities
                     if x.get("tenant_id") == tenant_id and x.get("entity_type") == "company"
                     and x.get("linkedin_urn") == resolved_urn), None)
    if existing:
        curst = existing.get("status")
        if curst != "deleted":
            existing["public_url"] = pu
            existing["display_name"] = display
            existing["raw_payload"] = raw
            existing["source_invocation_id"] = inv_id
            existing["status"] = "active" if curst in ("active", "stale") else curst
            existing["observed_at"] = ent_now
            existing["updated_at"] = ent_now
    else:
        entities.append({
            "id": _gen_id("li"),
            "tenant_id": tenant_id,
            "entity_type": "company",
            "linkedin_urn": resolved_urn,
            "public_url": pu,
            "email": None,
            "display_name": display,
            "company_linkedin_urn": None,
            "raw_payload": raw,
            "source_invocation_id": inv_id,
            "status": "active",
            "observed_at": ent_now,
            "created_at": ent_now,
            "updated_at": ent_now
        })
    _save("linkedin_entities.json", entities)

    # Response payload is normalized company
    response = {
        "company_urn": resolved_urn,
        "public_url": pu,
        "display_name": display,
        "entity": raw
    }
    inv["response_payload"] = response
    inv["http_status"] = 200
    inv["upstream_latency_ms"] = upstream_ms

    # Commit success + request counter increment
    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
            t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("tenants.json", tenants)

    _update_inv("succeeded")
    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                k["updated_at"] = k["last_used_at"]
                break
        _save("api_keys.json", api_keys)

    _save("tool_invocations.json", invocations)

    return {
        "tool": "get_linkedin_company",
        "invocation_id": inv_id,
        "company": response
    }

def get_linkedin_company_employees(company_urn, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(company_urn, str) or not company_urn.strip():
        return _err("VALIDATION_ERROR", "company_urn must be a non-empty string")
    cu = company_urn.strip()
    if not re.match(r"^urn:li:(fsd_company|company):[A-Za-z0-9]+$", cu):
        return _err("VALIDATION_ERROR", "company_urn format is invalid")
    if limit is None:
        lim = 25
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit <= 0 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        lim = limit
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    invocations = _load("tool_invocations.json")
    entities = _load("linkedin_entities.json")

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _norm_params(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _fp(tool_name, params, extacct_id):
        base = tool_name + "|" + _norm_params(params) + "|" + (extacct_id or "")
        return hashlib.sha256(base.encode("utf-8")).hexdigest()

    def _find_working_context():
        providers = ["linkedin_management", "linkedin", "linkedin_sales_navigator"]
        for t in tenants:
            if t.get("status") != "active":
                continue
            for p in providers:
                cands = [ea for ea in external_accounts
                         if ea.get("tenant_id") == t.get("id")
                         and ea.get("provider") == p
                         and ea.get("is_default_for_provider") is True
                         and ea.get("status") == "active"]
                if not cands:
                    continue
                k = None
                for ak in api_keys:
                    if ak.get("tenant_id") == t.get("id") and ak.get("status") == "active":
                        k = ak
                        break
                return t, k, cands[0]
        return None, None, None

    tenant, api_key, ext_acct = _find_working_context()
    if not tenant or not ext_acct:
        return _err("UNAUTHORIZED", "No active tenant/default LinkedIn external account available")
    tenant_id = tenant["id"]
    api_key_id = api_key["id"] if api_key else None
    external_account_id = ext_acct["id"]

    # Decode cursor as integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    params = {"company_urn": cu, "limit": lim, "cursor": cursor}
    fingerprint = _fp("get_linkedin_company_employees", params, external_account_id)

    inv_id = _gen_id("inv")
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": external_account_id,
        "tool_name": "get_linkedin_company_employees",
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fingerprint,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    def _update_inv(status, **fields):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = inv.get("status")
        if status != cur:
            if status not in allowed.get(cur, set()):
                inv["error_code"] = "INVALID_TRANSITION"
                inv["error_message"] = f"Illegal status transition {cur} -> {status}"
                inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("tool_invocations.json", invocations)
                return False, _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")
            inv["status"] = status
        for k, v in fields.items():
            inv[k] = v
        inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_invocations.json", invocations)
        return True, None

    # Quota enforcement before running
    if tenant.get("status") != "active":
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active")
        return _err("QUOTA_EXCEEDED", "Tenant is not active")
    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    if (isinstance(mrl, int) and mrl != 0 and mru >= mrl) or (not isinstance(mrl, int)):
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")

    if api_key_id is not None:
        akrow = next((x for x in api_keys if x.get("id") == api_key_id), None)
        if not akrow or akrow.get("status") != "active" or akrow.get("tenant_id") != tenant_id:
            _update_inv("failed", error_code="AUTH_FAILED", error_message="API key invalid for tenant")
            return _err("UNAUTHORIZED", "API key invalid for tenant")

    ok, e = _update_inv("running")
    if not ok:
        return e

    # Deterministic employee listing (offline)
    upstream_start = time.time()
    seed = cu.split(":")[-1]
    total = 137  # deterministic constant; could be derived, but stable is fine
    start = offset
    end = min(offset + lim, total)

    employees = []
    ent_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for i in range(start, end):
        uid = hashlib.sha256((seed + f"|emp|{i}").encode("utf-8")).hexdigest()[:12]
        profile_urn = f"urn:li:fsd_profile:{uid}"
        name = f"Employee {i+1}"
        emp = {
            "profile_urn": profile_urn,
            "display_name": name,
            "company_urn": cu,
            "title": "Employee",
            "public_url": f"https://www.linkedin.com/in/{uid}/"
        }
        employees.append(emp)

        # Upsert user_profile entity (relevant entity)
        existing = next((x for x in entities
                         if x.get("tenant_id") == tenant_id and x.get("entity_type") == "user_profile"
                         and x.get("linkedin_urn") == profile_urn), None)
        raw = {
            "urn": profile_urn,
            "name": name,
            "headline": emp["title"],
            "public_url": emp["public_url"],
            "company_urn": cu
        }
        if existing:
            if existing.get("status") != "deleted":
                existing["display_name"] = name
                existing["public_url"] = emp["public_url"]
                existing["company_linkedin_urn"] = cu
                existing["raw_payload"] = raw
                existing["source_invocation_id"] = inv_id
                existing["status"] = "active" if existing.get("status") in ("active", "stale") else existing.get("status")
                existing["observed_at"] = ent_now
                existing["updated_at"] = ent_now
        else:
            entities.append({
                "id": _gen_id("li"),
                "tenant_id": tenant_id,
                "entity_type": "user_profile",
                "linkedin_urn": profile_urn,
                "public_url": emp["public_url"],
                "email": None,
                "display_name": name,
                "company_linkedin_urn": cu,
                "raw_payload": raw,
                "source_invocation_id": inv_id,
                "status": "active",
                "observed_at": ent_now,
                "created_at": ent_now,
                "updated_at": ent_now
            })

    _save("linkedin_entities.json", entities)

    upstream_ms = int((time.time() - upstream_start) * 1000)

    next_cursor = None
    if end < total:
        next_cursor = base64.urlsafe_b64encode(str(end).encode("utf-8")).decode("utf-8").rstrip("=")

    response = {
        "company_urn": cu,
        "employees": employees,
        "limit": lim,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "total_estimate": total
    }
    inv["response_payload"] = response
    inv["http_status"] = 200
    inv["upstream_latency_ms"] = upstream_ms

    # Commit success + request increment
    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
            t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("tenants.json", tenants)

    _update_inv("succeeded")
    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                k["updated_at"] = k["last_used_at"]
                break
        _save("api_keys.json", api_keys)

    _save("tool_invocations.json", invocations)

    return {
        "tool": "get_linkedin_company_employees",
        "invocation_id": inv_id,
        "data": response
    }

def send_linkedin_post(text, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(text, str):
        return _err("VALIDATION_ERROR", "text must be a string")
    body = text.strip()
    if not body:
        return _err("VALIDATION_ERROR", "text must not be empty")
    if len(body) > 3000:
        return _err("VALIDATION_ERROR", "text is too long")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    invocations = _load("tool_invocations.json")
