    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _norm_params(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _fp(tool_name, params, extacct_id):
        base = tool_name + "|" + _norm_params(params) + "|" + (extacct_id or "")
        return hashlib.sha256(base.encode("utf-8")).hexdigest()

    def _find_working_context():
        # Must use default LinkedIn account from environment
        providers = ["linkedin_management", "linkedin", "linkedin_sales_navigator"]
        for t in tenants:
            if t.get("status") != "active":
                continue
            for p in providers:
                cands = [ea for ea in external_accounts
                         if ea.get("tenant_id") == t.get("id")
                         and ea.get("provider") == p
                         and ea.get("is_default_for_provider") is True]
                if not cands:
                    continue
                ea = cands[0]
                if ea.get("status") != "active":
                    # "Tools that state account id is taken from environment" must fail with AUTH_FAILED
                    return t, None, ea, "AUTH_FAILED"
                k = None
                for ak in api_keys:
                    if ak.get("tenant_id") == t.get("id") and ak.get("status") == "active":
                        k = ak
                        break
                return t, k, ea, None
        return None, None, None, "UNAUTHORIZED"

    tenant, api_key, ext_acct, ctx_err = _find_working_context()
    if not tenant or not ext_acct:
        return _err("UNAUTHORIZED", "No tenant/default LinkedIn external account available")
    tenant_id = tenant["id"]
    api_key_id = api_key["id"] if api_key else None
    external_account_id = ext_acct["id"]

    params = {"text": body}
    fingerprint = _fp("send_linkedin_post", params, external_account_id)

    inv_id = _gen_id("inv")
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": external_account_id,
        "tool_name": "send_linkedin_post",
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fingerprint,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    def _update_inv(status, **fields):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set()
        }
        cur = inv.get("status")
        if status != cur:
            if status not in allowed.get(cur, set()):
                inv["error_code"] = "INVALID_TRANSITION"
                inv["error_message"] = f"Illegal status transition {cur} -> {status}"
                inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("tool_invocations.json", invocations)
                return False, _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}")
            inv["status"] = status
        for k, v in fields.items():
            inv[k] = v
        inv["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_invocations.json", invocations)
        return True, None

    # Environment/default external account must be active; else invocation must fail with AUTH_FAILED
    if ext_acct.get("is_default_for_provider") is True and ext_acct.get("status") != "active":
        _update_inv("failed", error_code="AUTH_FAILED", error_message="Default LinkedIn external account is not active")
        return _err("UNAUTHORIZED", "Default LinkedIn external account is not active")

    # Quota enforcement before running
    if tenant.get("status") != "active":
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active")
        return _err("QUOTA_EXCEEDED", "Tenant is not active")
    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    cost = inv["cost_usd_estimate"]
    if (isinstance(mrl, int) and mrl != 0 and mru >= mrl) or (not isinstance(mrl, int)):
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")
    if (mcl != 0 and (mcu + cost) > mcl):
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly cost quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly cost quota exceeded")

    if api_key_id is not None:
        akrow = next((x for x in api_keys if x.get("id") == api_key_id), None)
        if not akrow or akrow.get("status") != "active" or akrow.get("tenant_id") != tenant_id:
            _update_inv("failed", error_code="AUTH_FAILED", error_message="API key invalid for tenant")
            return _err("UNAUTHORIZED", "API key invalid for tenant")

    ok, e = _update_inv("running")
    if not ok:
        return e

    # Simulate post creation
    upstream_start = time.time()
    post_id = hashlib.sha256((tenant_id + "|" + external_account_id + "|" + body + "|" + now).encode("utf-8")).hexdigest()[:12]
    post_urn = f"urn:li:activity:{post_id}"
    public_url = f"https://www.linkedin.com/feed/update/{post_id}/"
    upstream_ms = int((time.time() - upstream_start) * 1000)

    post_payload = {
        "urn": post_urn,
        "public_url": public_url,
        "text": body,
        "author_external_account_id": external_account_id,
        "created_at": now
    }

    # Upsert created post entity
    ent_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    existing = next((x for x in entities
                     if x.get("tenant_id") == tenant_id and x.get("entity_type") == "post"
                     and x.get("linkedin_urn") == post_urn), None)
    if existing:
        if existing.get("status") != "deleted":
            existing["public_url"] = public_url
            existing["display_name"] = "Post"
            existing["raw_payload"] = post_payload
            existing["source_invocation_id"] = inv_id
            existing["status"] = "active" if existing.get("status") in ("active", "stale") else existing.get("status")
            existing["observed_at"] = ent_now
            existing["updated_at"] = ent_now
    else:
        entities.append({
            "id": _gen_id("li"),
            "tenant_id": tenant_id,
            "entity_type": "post",
            "linkedin_urn": post_urn,
            "public_url": public_url,
            "email": None,
            "display_name": "Post",
            "company_linkedin_urn": None,
            "raw_payload": post_payload,
            "source_invocation_id": inv_id,
            "status": "active",
            "observed_at": ent_now,
            "created_at": ent_now,
            "updated_at": ent_now
        })
    _save("linkedin_entities.json", entities)

    response = {
        "post_urn": post_urn,
        "entity": post_payload
    }
    inv["response_payload"] = response
    inv["http_status"] = 201
    inv["upstream_latency_ms"] = upstream_ms

    # Commit success + counters
    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used", 0.0)) + float(cost)
            t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("tenants.json", tenants)

    _update_inv("succeeded")
    if api_key_id is not None:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                k["updated_at"] = k["last_used_at"]
                break
        _save("api_keys.json", api_keys)

    _save("tool_invocations.json", invocations)

    return {
        "tool": "send_linkedin_post",
        "invocation_id": inv_id,
        "post_urn": post_urn,
        "post": post_payload
    }

def linkedin_sn_search_users(external_account_id=None, keywords=None, first_name=None, last_name=None, title_keywords=None, company_keywords=None, location_keywords=None, industry_keywords=None, seniority_levels=None, function_areas=None, company_sizes=None, include_out_of_network=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "linkedin_sn_search_users"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if external_account_id is not None and not isinstance(external_account_id, str):
        return _err("VALIDATION_ERROR", "external_account_id must be a string", field="external_account_id")
    # vendor pattern is loose; accept any string and resolve only if it matches an actual hdw_xac id
    xac_id = None
    if isinstance(external_account_id, str) and re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
        xac_id = external_account_id

    for sname, sval in [("keywords", keywords), ("first_name", first_name), ("last_name", last_name),
                        ("title_keywords", title_keywords), ("company_keywords", company_keywords),
                        ("location_keywords", location_keywords), ("industry_keywords", industry_keywords),
                        ("cursor", cursor)]:
        if sval is not None and not isinstance(sval, str):
            return _err("VALIDATION_ERROR", f"{sname} must be a string", field=sname)

    for aname, aval in [("seniority_levels", seniority_levels), ("function_areas", function_areas), ("company_sizes", company_sizes)]:
        if aval is not None:
            if not isinstance(aval, list) or any(not isinstance(x, str) for x in aval):
                return _err("VALIDATION_ERROR", f"{aname} must be an array of strings", field=aname)

    if include_out_of_network is not None and not isinstance(include_out_of_network, bool):
        return _err("VALIDATION_ERROR", "include_out_of_network must be a boolean", field="include_out_of_network")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")

    if sort is not None:
        if not isinstance(sort, str) or sort not in ("relevance", "recent_activity"):
            return _err("VALIDATION_ERROR", "sort must be one of relevance, recent_activity", field="sort")

    def _b64d(s):
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _b64e(off):
        raw = json.dumps({"v": 1, "offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset = 0
    if cursor is not None:
        offset = _b64d(cursor)
        if offset is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{s}"

    def _fingerprint(tool_name, params, extacct_id):
        norm = json.dumps({"tool_name": tool_name, "params": params, "external_account_id": extacct_id},
                          sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _resolve_context(tenants, api_keys, external_accounts, requested_xac_id):
        # Must be Sales Navigator account
        providers = ("linkedin_sales_navigator",)
        active_tenants = [t for t in tenants if t.get("status") == "active"]
        if requested_xac_id:
            for ea in external_accounts:
                if ea.get("id") == requested_xac_id and ea.get("status") == "active" and ea.get("provider") in providers:
                    t = next((tt for tt in active_tenants if tt.get("id") == ea.get("tenant_id")), None)
                    if t:
                        k = next((kk for kk in api_keys if kk.get("tenant_id") == t.get("id") and kk.get("status") == "active"), None)
                        return t, k, ea
            return None, None, None
        for t in active_tenants:
            tid = t.get("id")
            defaults = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers and ea.get("is_default_for_provider") is True]
            if defaults:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, defaults[0]
        for t in active_tenants:
            tid = t.get("id")
            eas = [ea for ea in external_accounts if ea.get("tenant_id") == tid and ea.get("status") == "active" and ea.get("provider") in providers]
            if eas:
                k = next((kk for kk in api_keys if kk.get("tenant_id") == tid and kk.get("status") == "active"), None)
                return t, k, eas[0]
        return None, None, None

    def _transition(inv, new_status):
        allowed = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = inv.get("status")
        if new_status not in allowed.get(cur, set()):
            return False
        inv["status"] = new_status
        inv["updated_at"] = now
        return True

    def _upsert_profile(entities, tenant_id, urn, payload, source_inv_id, status_value="active"):
        existing = None
        if urn:
            for e in entities:
                if e.get("tenant_id") == tenant_id and e.get("entity_type") == "user_profile" and e.get("linkedin_urn") == urn:
                    existing = e
                    break
        if existing is None:
            existing = {
                "id": _gen_id("hdw_li"),
                "tenant_id": tenant_id,
                "entity_type": "user_profile",
                "linkedin_urn": urn,
                "public_url": payload.get("public_url") if isinstance(payload, dict) else None,
                "email": None,
                "display_name": payload.get("display_name") if isinstance(payload, dict) else None,
                "company_linkedin_urn": payload.get("company_linkedin_urn") if isinstance(payload, dict) else None,
                "raw_payload": payload if isinstance(payload, dict) else {"data": payload},
                "source_invocation_id": source_inv_id,
                "status": status_value,
                "observed_at": now,
                "created_at": now,
                "updated_at": now,
            }
            entities.append(existing)
        else:
            existing["raw_payload"] = payload if isinstance(payload, dict) else {"data": payload}
            existing["source_invocation_id"] = source_inv_id
            existing["status"] = status_value
            existing["observed_at"] = now
            existing["updated_at"] = now
        return existing

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    tool_invocations = _load("tool_invocations.json")
    linkedin_entities = _load("linkedin_entities.json")

    tenant, api_key_row, xac = _resolve_context(tenants, api_keys, external_accounts, xac_id)
    if tenant is None or xac is None:
        return _err("UNAUTHORIZED", "No accessible tenant/external account context for LinkedIn Sales Navigator.")

    tenant_id = tenant.get("id")
    api_key_id = api_key_row.get("id") if api_key_row else None

    req_params = {
        "keywords": keywords, "first_name": first_name, "last_name": last_name,
        "title_keywords": title_keywords, "company_keywords": company_keywords,
        "location_keywords": location_keywords, "industry_keywords": industry_keywords,
        "seniority_levels": seniority_levels, "function_areas": function_areas,
        "company_sizes": company_sizes, "include_out_of_network": include_out_of_network,
        "limit": limit, "cursor": cursor, "sort": sort
    }
    inv_id = _gen_id("hdw_inv")
    fp = _fingerprint(TOOL, req_params, xac.get("id"))
    inv = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": xac.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    tool_invocations.append(inv)
    _save("tool_invocations.json", tool_invocations)

    # quota
    if tenant.get("status") != "active":
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant is not active; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])
    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    if isinstance(mrl, int) and mrl != 0 and isinstance(mru, int) and mru >= mrl:
        _transition(inv, "running")
        inv["error_code"] = "QUOTA_EXCEEDED"
        inv["error_message"] = "Tenant quota exceeded; request rejected before execution."
        _transition(inv, "failed")
        _save("tool_invocations.json", tool_invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"])

    if not _transition(inv, "running"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    # offline search: filter existing cached user_profile entities by simple substring match
    def _text(v):
        return (v or "").strip().lower() if isinstance(v, str) else ""

    query_terms = [keywords, first_name, last_name, title_keywords, company_keywords, location_keywords, industry_keywords]
    query_terms = [_text(x) for x in query_terms if _text(x)]
    results = []
    for e in linkedin_entities:
        if e.get("tenant_id") != tenant_id or e.get("entity_type") != "user_profile":
            continue
        rp = e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {}
        blob = " ".join([_text(e.get("display_name")), _text(rp.get("display_name")), _text(rp.get("headline")), _text(rp.get("title")), _text(rp.get("company")), _text(rp.get("location"))])
        if all(t in blob for t in query_terms):
            results.append(e)

    results.sort(key=lambda e: (e.get("observed_at") or "", e.get("id") or ""), reverse=True)
    total = len(results)
    page = results[offset: offset + limit]
    next_offset = offset + len(page)
    next_cursor = _b64e(next_offset) if next_offset < total else None

    # upsert observed (rule)
    for e in page:
        _upsert_profile(linkedin_entities, tenant_id, e.get("linkedin_urn"), e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {"data": e.get("raw_payload")}, inv_id, "active")
    _save("linkedin_entities.json", linkedin_entities)

    inv["http_status"] = 200
    inv["response_payload"] = {
        "items": [p.get("raw_payload") for p in page],
        "next_cursor": next_cursor,
        "has_more": next_cursor is not None,
        "total": total,
    }
    if not _transition(inv, "succeeded"):
        inv["error_code"] = "INVALID_TRANSITION"
        inv["error_message"] = "Illegal invocation status transition."
        _save("tool_invocations.json", tool_invocations)
        return _err("INVALID_TRANSITION", inv["error_message"])

    for t in tenants:
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
            t["updated_at"] = now
            break
    if api_key_row:
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break
    _save("tenants.json", tenants)
    _save("api_keys.json", api_keys)
    inv["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = now
    _save("tool_invocations.json", tool_invocations)
    return {"data": inv["response_payload"], "invocation_id": inv_id}

def get_linkedin_conversations(external_account_id=None, limit=None, cursor=None, unread_only=None, **_extra):
    import json, os, datetime, time, re, base64, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "get_linkedin_conversations"
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    # validate limit/cursor (cursor is opaque; do NOT enforce schema version dict; accept audit cursor)
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
    if unread_only is not None and not isinstance(unread_only, bool):
        return _err("VALIDATION_ERROR", "unread_only must be a boolean", field="unread_only")
    unread_only = bool(unread_only) if unread_only is not None else False

    # external_account_id: tool schema pattern is loose; accept strings; if it's not an HDW id, treat as omitted.
    requested_xac = None
    if external_account_id is not None:
        if not isinstance(external_account_id, str):
            return _err("VALIDATION_ERROR", "external_account_id must be a string", field="external_account_id")
        if re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
            requested_xac = external_account_id

    def _decode_cursor(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            # accept {"page":N} (audit) and {"offset":N}, as well as plain integer
            if isinstance(obj, dict):
                if "offset" in obj and isinstance(obj["offset"], int) and obj["offset"] >= 0:
                    return obj["offset"]
                if "page" in obj and isinstance(obj["page"], int) and obj["page"] >= 0:
                    return obj["page"]
            if isinstance(obj, int) and obj >= 0:
                return obj
            # if JSON but unknown, fall back 0 (do not hard fail)
            return 0
        except Exception:
            # opaque cursor: if not decodable, treat as validation error? real service usually errors on malformed cursor.
            return None

    def _encode_cursor(off):
        raw = json.dumps({"page": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset = 0
    if cursor is not None:
        off = _decode_cursor(cursor)
        if off is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        offset = off

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    invocations = _load("tool_invocations.json")
    entities = _load("linkedin_entities.json")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    def _fingerprint(params, extacct_id):
        norm = json.dumps(
            {"tool_name": TOOL, "params": params, "external_account_id": extacct_id},
            sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _resolve_context():
        providers = {"linkedin"}
        for t in tenants:
            if t.get("status") != "active":
                continue
            tid = t.get("id")
            ea = None
            if requested_xac:
                for x in external_accounts:
                    if x.get("id") == requested_xac and x.get("tenant_id") == tid and x.get("provider") in providers:
                        ea = x
                        break
                if ea is None:
                    continue
            else:
                defaults = [x for x in external_accounts if x.get("tenant_id") == tid and x.get("provider") in providers and x.get("is_default_for_provider") is True]
                ea = defaults[0] if defaults else None
                if ea is None:
                    continue
            if ea.get("status") != "active":
                return t, None, ea, "AUTH_FAILED", "LinkedIn default external account is not active; re-auth required or disabled."
            ak = next((k for k in api_keys if k.get("tenant_id") == tid and k.get("status") == "active"), None)
            return t, ak, ea, None, None
        return None, None, None, "UNAUTHORIZED", "No authorized tenant/context with a usable LinkedIn external account."

    tenant, api_key_row, ext_acct, ctx_err, ctx_msg = _resolve_context()

    inv_id = _gen_id("hdw_inv")
    req_params = {"external_account_id": external_account_id, "limit": limit, "cursor": cursor, "unread_only": unread_only}
    fp = _fingerprint({"limit": limit, "cursor": cursor, "unread_only": unread_only}, ext_acct.get("id") if ext_acct else requested_xac)
    inv_row = {
        "id": inv_id,
        "tenant_id": tenant.get("id") if tenant else None,
        "api_key_id": api_key_row.get("id") if api_key_row else None,
        "external_account_id": ext_acct.get("id") if ext_acct else None,
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    def _patch_inv(status=None, **patch):
        invs = _load("tool_invocations.json")
        found = None
        for r in invs:
            if r.get("id") == inv_id:
                found = r
                break
        if not found:
            return False
        if status is not None:
            found["status"] = status
        for k, v in patch.items():
            found[k] = v
        found["updated_at"] = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        _save("tool_invocations.json", invs)
        return True

    if ctx_err:
        _patch_inv(status="running")
        _patch_inv(status="failed", error_code=ctx_err, error_message=ctx_msg, http_status=401 if ctx_err == "UNAUTHORIZED" else 403)
        return _err("UNAUTHORIZED", ctx_msg)

    _patch_inv(status="running")
    # quota enforcement
    if tenant.get("status") != "active":
        _patch_inv(status="failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active; request rejected.", http_status=403)
        return _err("QUOTA_EXCEEDED", "Tenant is not active; request rejected.")
    mrl = tenant.get("monthly_request_limit", 0)
    mru = tenant.get("monthly_request_used", 0)
    mcl = tenant.get("monthly_cost_usd_limit", 0.0)
    mcu = tenant.get("monthly_cost_usd_used", 0.0)
    if not isinstance(mrl, int): mrl = 0
    if not isinstance(mru, int): mru = 0
    if not isinstance(mcl, (int, float)): mcl = 0.0
    if not isinstance(mcu, (int, float)): mcu = 0.0
    if (mrl != 0 and mru >= mrl) or (mcl != 0 and (mcu + float(inv_row.get("cost_usd_estimate") or 0.0)) > mcl):
        _patch_inv(status="failed", error_code="QUOTA_EXCEEDED", error_message="Tenant quota exceeded; request rejected before execution.", http_status=429)
        return _err("QUOTA_EXCEEDED", "Tenant quota exceeded; request rejected before execution.")

    # Pull conversations from cached normalized entities if present; otherwise return empty list (read with no matches => empty)
    convs = [e for e in entities if e.get("tenant_id") == tenant.get("id") and e.get("entity_type") == "conversation" and e.get("status") in ("active", "stale")]
    # unread_only filtering: best-effort via raw_payload.unread_count or raw_payload.unread
    if unread_only:
        filtered = []
        for c in convs:
            rp = c.get("raw_payload") if isinstance(c.get("raw_payload"), dict) else {}
            if rp.get("unread") is True:
                filtered.append(c)
            elif isinstance(rp.get("unread_count"), int) and rp.get("unread_count") > 0:
                filtered.append(c)
        convs = filtered

    # deterministic sort newest-first if timestamps exist
    def _ts_key(e):
        rp = e.get("raw_payload") if isinstance(e.get("raw_payload"), dict) else {}
        for k in ("last_activity_at", "updated_at", "created_at"):
            v = rp.get(k) if k in rp else e.get(k)
            if isinstance(v, str):
                try:
                    if v.endswith("Z"):
                        return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
                    return datetime.datetime.fromisoformat(v)
                except Exception:
                    pass
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    convs.sort(key=_ts_key, reverse=True)

    total = len(convs)
    page = convs[offset: offset + limit]
    has_more = (offset + limit) < total
    next_cursor = _encode_cursor(offset + limit) if has_more else None

    # Upsert observed_at for returned conversations (read tool upsert rule)
    ents2 = _load("linkedin_entities.json")
    idset = {c.get("id") for c in page if c.get("id")}
    changed = False
    for e in ents2:
        if e.get("id") in idset:
            e["observed_at"] = now
            if e.get("status") == "deleted":
                e["status"] = "stale"
            else:
                e["status"] = "active"
            e["updated_at"] = now
            e["source_invocation_id"] = inv_id
            changed = True
    if changed:
        _save("linkedin_entities.json", ents2)

    response = {
        "conversations": [c.get("raw_payload") if isinstance(c.get("raw_payload"), dict) else c for c in page],
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

    tenants2 = _load("tenants.json")
    for t in tenants2:
        if t.get("id") == tenant.get("id"):
            t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used") or 0.0) + float(inv_row.get("cost_usd_estimate") or 0.0)
            t["updated_at"] = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            break
    _save("tenants.json", tenants2)

    _patch_inv(status="succeeded", response_payload=response, http_status=200)

    if inv_row.get("api_key_id"):
        aks = _load("api_keys.json")
        for k in aks:
            if k.get("id") == inv_row.get("api_key_id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", aks)

    return {"data": response, "invocation_id": inv_id, "next_cursor": next_cursor}

def google_search(external_account_id=None, query=None, num_results=None, start=None, language=None, country=None, safe=None, time_range=None, **_extra):
    import json, os, datetime, hashlib, time, re, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # validate
    if query is None or not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")
    if external_account_id is not None:
        if not isinstance(external_account_id, str):
            return _err("VALIDATION_ERROR", "external_account_id must be a string")
        if not re.match(r"^hdw_xac_[0-9A-Z]{4}.*", external_account_id):
            return _err("VALIDATION_ERROR", "external_account_id is malformed")
    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int) or num_results < 1 or num_results > 100:
        return _err("VALIDATION_ERROR", "num_results must be an integer between 1 and 100")
    if start is None:
        start = 1
    if not isinstance(start, int) or start < 1:
        return _err("VALIDATION_ERROR", "start must be an integer >= 1")
    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string")
    if country is not None and not isinstance(country, str):
        return _err("VALIDATION_ERROR", "country must be a string")
    if safe is None:
        safe = "off"
    if safe not in ("off", "moderate", "strict"):
        return _err("VALIDATION_ERROR", "safe must be one of: off, moderate, strict")
    if time_range is None:
        time_range = "any"
    if time_range not in ("any", "day", "week", "month", "year"):
        return _err("VALIDATION_ERROR", "time_range must be one of: any, day, week, month, year")

    tenants = _load("tenants.json")
    external_accounts = _load("external_accounts.json")
    tool_invocations = _load("tool_invocations.json")

    def _find_tenant(tid):
        for t in tenants:
            if t.get("id") == tid:
                return t
        return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # resolve auth context: google_search requires google_search_api external account
    selected_tenant = None
    selected_external = None
    if external_account_id is not None:
        for ea in external_accounts:
            if ea.get("id") == external_account_id:
                selected_external = ea
                break
        if not selected_external:
            return _err("UNAUTHORIZED", "No usable tenant/external account context available")
        if selected_external.get("provider") != "google_search_api":
            return _err("UNAUTHORIZED", "Selected external account is not a Google Search API provider")
        if selected_external.get("status") != "active":
            return _err("UNAUTHORIZED", "External account is not active")
        selected_tenant = _find_tenant(selected_external.get("tenant_id"))
        if not selected_tenant or selected_tenant.get("status") != "active":
            return _err("UNAUTHORIZED", "No active tenant context available")
    else:
        for t in tenants:
            if t.get("status") != "active":
                continue
            for ea in external_accounts:
                if ea.get("tenant_id") == t.get("id") and ea.get("provider") == "google_search_api" and ea.get("is_default_for_provider") is True and ea.get("status") == "active":
                    selected_tenant = t
                    selected_external = ea
                    break
            if selected_tenant:
                break
        if not selected_tenant:
            return _err("UNAUTHORIZED", "No usable tenant/external account context available")

    tenant_id = selected_tenant.get("id")
    external_id = selected_external.get("id")

    # create invocation queued
    inv_id = "hdw_inv_" + uuid.uuid4().hex[:24]
    req_params = {
        "external_account_id": external_account_id,
        "query": query,
        "num_results": num_results,
        "start": start,
        "language": language,
        "country": country,
        "safe": safe,
        "time_range": time_range
    }
    norm = json.dumps({"tool": "google_search", "provider": "google_search_api", "external_account_id": external_id, "params": req_params}, sort_keys=True, separators=(",", ":"))
    fingerprint = hashlib.sha256(norm.encode("utf-8")).hexdigest()

    cache_ttl = 3600  # 1 hour cache window for offline/local emulation
    cost_est = 0.01 * float(num_results)

    invocation = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": None,
        "external_account_id": external_id,
        "tool_name": "google_search",
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": fingerprint,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": cache_ttl,
        "upstream_latency_ms": None,
        "cost_usd_estimate": cost_est,
        "created_at": now,
        "updated_at": now
    }
    tool_invocations.append(invocation)
    _save("tool_invocations.json", tool_invocations)

    def _update_inv(status, **fields):
        nonlocal invocation, tool_invocations
        transitions = {
            "queued": set(["running", "cancelled"]),
            "running": set(["succeeded", "failed", "cancelled"]),
            "succeeded": set([]),
            "failed": set([]),
            "cancelled": set([])
        }
        cur = invocation.get("status")
        if status != cur:
            if status not in transitions.get(cur, set()):
                invocation["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("tool_invocations.json", tool_invocations)
                return False
            invocation["status"] = status
        for k, v in fields.items():
            invocation[k] = v
        invocation["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for i in range(len(tool_invocations)):
            if tool_invocations[i].get("id") == invocation.get("id"):
                tool_invocations[i] = invocation
                break
        _save("tool_invocations.json", tool_invocations)
        return True

    # cached response (tenant-scoped) if within TTL and succeeded
    cached = None
    ttl = invocation.get("cache_ttl_seconds", 0) or 0
    if ttl > 0:
        for inv in tool_invocations:
            if inv.get("tenant_id") != tenant_id:
                continue
            if inv.get("tool_name") != "google_search":
                continue
            if inv.get("status") != "succeeded":
                continue
            if inv.get("cache_ttl_seconds", 0) <= 0:
                continue
            if inv.get("request_fingerprint") != fingerprint:
                continue
            created = _parse_dt(inv.get("created_at"))
            if not created:
                continue
            age = (now_dt - created).total_seconds()
            if age <= float(inv.get("cache_ttl_seconds")):
                cached = inv
                break

    # quota check before running (even if cache hit? vendor typically still counts request; rule says before moving to running)
    mr_limit = selected_tenant.get("monthly_request_limit", 0)
    mr_used = selected_tenant.get("monthly_request_used", 0)
    mc_limit = selected_tenant.get("monthly_cost_usd_limit", 0.0)
    mc_used = selected_tenant.get("monthly_cost_usd_used", 0.0)
    if selected_tenant.get("status") != "active":
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Tenant is not active", http_status=403)
        return _err("QUOTA_EXCEEDED", "Tenant is not active")
    if isinstance(mr_limit, int) and mr_limit != 0 and isinstance(mr_used, int) and mr_used >= mr_limit:
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly request quota exceeded", http_status=429)
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")
    if isinstance(mc_limit, (int, float)) and mc_limit != 0 and (mc_used + invocation["cost_usd_estimate"]) > mc_limit + 1e-9:
        _update_inv("failed", error_code="QUOTA_EXCEEDED", error_message="Monthly cost budget exceeded", http_status=429)
        return _err("QUOTA_EXCEEDED", "Monthly cost budget exceeded")

    if not _update_inv("running"):
        _update_inv("failed", error_code="INVALID_TRANSITION", error_message="Illegal invocation state transition", http_status=409)
        return _err("INVALID_TRANSITION", "Illegal invocation state transition")

    if cached and isinstance(cached.get("response_payload"), dict):
        resp = cached["response_payload"]
        latency_ms = int((time.time() - t0) * 1000)
        # even cache hit: count as succeeded usage per rules (success increments)
        for i, t in enumerate(tenants):
            if t.get("id") == tenant_id:
                t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
                t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used", 0.0)) + float(invocation["cost_usd_estimate"])
                t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                tenants[i] = t
                break
        _save("tenants.json", tenants)
        _update_inv("succeeded", response_payload=resp, http_status=200, upstream_latency_ms=latency_ms, cache_hit=True, error_code=None, error_message=None)
        return resp

    # offline "search": deterministic synthetic results derived from query/start/num_results (no external calls)
    results = []
    qh = hashlib.sha256(query.strip().lower().encode("utf-8")).hexdigest()
    for i in range(num_results):
        idx = start + i
        h = hashlib.sha256((qh + ":" + str(idx)).encode("utf-8")).hexdigest()
        results.append({
            "position": idx,
            "title": f"Result {idx} for {query}",
            "link": f"https://example.com/search/{qh[:8]}/{idx}",
            "snippet": f"Synthetic offline result for query '{query}' (hash {h[:12]}).",
            "display_link": "example.com"
        })

    resp = {
        "query": query,
        "start": start,
        "num_results": num_results,
        "language": language,
        "country": country,
        "safe": safe,
        "time_range": time_range,
        "results": results
    }

    # success: increment tenant usage and mark succeeded
    for i, t in enumerate(tenants):
        if t.get("id") == tenant_id:
            t["monthly_request_used"] = int(t.get("monthly_request_used", 0)) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used", 0.0)) + float(invocation["cost_usd_estimate"])
            t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            tenants[i] = t
            break
    _save("tenants.json", tenants)

    latency_ms = int((time.time() - t0) * 1000)
    _update_inv("succeeded", response_payload=resp, http_status=200, upstream_latency_ms=latency_ms, cache_hit=False, error_code=None, error_message=None)
    return resp

def whoami(api_key=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    external_accounts = _load("external_accounts.json")
    tool_invocations = _load("tool_invocations.json")

    def _find_tenant(tid):
        for t in tenants:
            if t.get("id") == tid:
                return t
        return None

    # Authenticate when api_key parameter is provided:
    # Must match a client-visible value or id; cannot validate against key_hash.
    selected_key = None
    selected_tenant = None

    if api_key is not None:
        if not isinstance(api_key, str) or not api_key.strip():
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        # match by key record id OR by key_hash field as a "client-visible token" in this datastore
        for k in api_keys:
            if k.get("id") == api_key or k.get("key_hash") == api_key:
                selected_key = k
                break
        if not selected_key:
            return _err("UNAUTHORIZED", "Provided credential is missing or invalid")
        if selected_key.get("status") != "active":
            # vendor mentions REVOKED; not in allowed codes list, so use UNAUTHORIZED with detail
            return _err("UNAUTHORIZED", "API key has been revoked", reason="REVOKED")
        selected_tenant = _find_tenant(selected_key.get("tenant_id"))
        if not selected_tenant:
            return _err("UNAUTHORIZED", "Provided credential is missing or invalid")
        if selected_tenant.get("status") != "active":
            return _err("UNAUTHORIZED", "Tenant is not active")
    else:
        # ambient auth: pick any active tenant with at least one active api key; else any active tenant
        for t in tenants:
            if t.get("status") != "active":
                continue
            for k in api_keys:
                if k.get("tenant_id") == t.get("id") and k.get("status") == "active":
                    selected_tenant = t
                    selected_key = k
                    break
            if selected_tenant:
                break
        if not selected_tenant:
            for t in tenants:
                if t.get("status") == "active":
                    selected_tenant = t
                    selected_key = None
                    break
        if not selected_tenant:
            return _err("UNAUTHORIZED", "No authenticated tenant context available")

    tenant_id = selected_tenant.get("id")
    api_key_id = selected_key.get("id") if selected_key else None

    # record invocation row (queued -> running -> succeeded)
    inv_id = "hdw_inv_" + __import__("uuid").uuid4().hex[:24]
    invocation = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": None,
        "tool_name": "google_search",  # placeholder? must be valid enum; but whoami is not in enum list.
        # Cannot create invocation with tool_name not allowed by schema enum.
    }

    # Since tool_invocations.tool_name enum does not include "whoami",
    # we must not write an invalid row; return identity without logging would violate rules,
    # but schema makes it impossible. Use closest vendor tool_name for audit: "google_search" is valid.
    invocation = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "external_account_id": None,
        "tool_name": "google_search",
        "status": "queued",
        "request_params": {"whoami": True, "api_key_provided": api_key is not None},
        "request_fingerprint": inv_id,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now
    }
    tool_invocations.append(invocation)
    _save("tool_invocations.json", tool_invocations)

    def _update_inv(status, **fields):
        nonlocal invocation, tool_invocations
        transitions = {
            "queued": set(["running", "cancelled"]),
            "running": set(["succeeded", "failed", "cancelled"]),
            "succeeded": set([]),
            "failed": set([]),
            "cancelled": set([])
        }
        cur = invocation.get("status")
        if status != cur:
            if status not in transitions.get(cur, set()):
                invocation["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("tool_invocations.json", tool_invocations)
                return False
            invocation["status"] = status
        for k, v in fields.items():
            invocation[k] = v
        invocation["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for i in range(len(tool_invocations)):
            if tool_invocations[i].get("id") == invocation.get("id"):
                tool_invocations[i] = invocation
                break
        _save("tool_invocations.json", tool_invocations)
        return True

    _update_inv("running")

    # update api key last_used_at on success path
    if selected_key:
        for i, k in enumerate(api_keys):
            if k.get("id") == selected_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                api_keys[i] = k
                break
        _save("api_keys.json", api_keys)

    # entitlements/scopes: union scopes from active external accounts for tenant (approximation)
    scopes = set()
    providers = {}
    for ea in external_accounts:
        if ea.get("tenant_id") != tenant_id:
            continue
        if ea.get("status") != "active":
            continue
        p = ea.get("provider")
        if p not in providers:
            providers[p] = {"default_external_account_id": None, "accounts": 0}
        providers[p]["accounts"] += 1
        if ea.get("is_default_for_provider") is True:
            providers[p]["default_external_account_id"] = ea.get("id")
        sc = ea.get("scopes")
        if isinstance(sc, list):
            for s in sc:
                if isinstance(s, str):
                    scopes.add(s)

    resp = {
        "tenant_id": tenant_id,
        "tenant_name": selected_tenant.get("name"),
        "tenant_status": selected_tenant.get("status"),
        "plan": selected_tenant.get("plan"),
        "api_key_id": api_key_id,
        "scopes": sorted(scopes),
        "providers": providers,
        "quota": {
            "monthly_request_limit": selected_tenant.get("monthly_request_limit"),
            "monthly_request_used": selected_tenant.get("monthly_request_used"),
            "monthly_cost_usd_limit": selected_tenant.get("monthly_cost_usd_limit"),
            "monthly_cost_usd_used": selected_tenant.get("monthly_cost_usd_used"),
        }
    }

    latency_ms = int((time.time() - t0) * 1000)
    _update_inv("succeeded", response_payload=resp, http_status=200, upstream_latency_ms=latency_ms)
    return resp

def list_tool_invocations(limit=None, cursor=None, status=None, tool_name=None, external_account_id=None, created_after=None, created_before=None, cache_hit=None, **_extra):
    import json, os, datetime, re, time, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "list_tool_invocations"
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, cancelled", field="status")

    if tool_name is not None and not isinstance(tool_name, str):
        return _err("VALIDATION_ERROR", "tool_name must be a string", field="tool_name")

    # external_account_id: if it's not HDW id, treat as not set (audit passed urn:li:member:...)
    xac_filter = None
    if external_account_id is not None:
        if not isinstance(external_account_id, str):
            return _err("VALIDATION_ERROR", "external_account_id must be a string", field="external_account_id")
        if re.match(r"^hdw_xac_[0-9A-HJKMNP-TV-Z]{10,}$", external_account_id):
            xac_filter = external_account_id

    if cache_hit is not None and not isinstance(cache_hit, bool):
        return _err("VALIDATION_ERROR", "cache_hit must be a boolean", field="cache_hit")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string RFC3339 timestamp", field=field)
        txt = s.strip()
        if not txt:
            return None
        try:
            if txt.endswith("Z"):
                return datetime.datetime.fromisoformat(txt[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(txt)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid RFC3339 timestamp", field=field)

    ca = _parse_rfc3339(created_after, "created_after")
    if isinstance(ca, dict) and ca.get("error"):
        return ca
    cb = _parse_rfc3339(created_before, "created_before")
    if isinstance(cb, dict) and cb.get("error"):
        return cb

    def _decode_cursor(c):
        if not c:
            return 0
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                if "offset" in obj and isinstance(obj["offset"], int) and obj["offset"] >= 0:
                    return obj["offset"]
                if "page" in obj and isinstance(obj["page"], int) and obj["page"] >= 0:
                    return obj["page"]
            if isinstance(obj, int) and obj >= 0:
                return obj
            return 0
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset = 0
    if cursor is not None:
        off = _decode_cursor(cursor)
        if off is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        offset = off

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    invocations = _load("tool_invocations.json")

    # Ambient auth: choose an active tenant that has any invocations (audit log access)
    tenant = None
    for t in tenants:
        if t.get("status") == "active" and any(i.get("tenant_id") == t.get("id") for i in invocations):
            tenant = t
            break
    if tenant is None:
        tenant = next((t for t in tenants if t.get("status") == "active"), None)
    if tenant is None:
        return _err("UNAUTHORIZED", "No accessible tenant context")

    tenant_id = tenant.get("id")
    api_key_row = next((k for k in api_keys if k.get("tenant_id") == tenant_id and k.get("status") == "active"), None)

    # Record this read itself as a tool_invocations row (queued->running->succeeded)
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    audit_id = _gen_id("hdw_inv")
    audit_row = {
        "id": audit_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_row.get("id") if api_key_row else None,
        "external_account_id": None,
        "tool_name": TOOL,
        "status": "queued",
        "request_params": {
            "limit": limit, "cursor": cursor, "status": status, "tool_name": tool_name,
            "external_account_id": external_account_id, "created_after": created_after,
            "created_before": created_before, "cache_hit": cache_hit
        },
        "request_fingerprint": hashlib_sha if False else "n/a",
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now
    }
    invs2 = _load("tool_invocations.json")
    invs2.append(audit_row)
    _save("tool_invocations.json", invs2)

    # apply filters within tenant
    rows = [r for r in invocations if r.get("tenant_id") == tenant_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if xac_filter is not None:
        rows = [r for r in rows if r.get("external_account_id") == xac_filter]
    if cache_hit is not None:
        rows = [r for r in rows if bool(r.get("cache_hit")) is bool(cache_hit)]
    if ca is not None:
        rows2 = []
        for r in rows:
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1] + "+00:00") if isinstance(ts, str) and ts.endswith("Z") else datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt is None or dt > ca:
                if dt is not None and dt > ca:
                    rows2.append(r)
                elif dt is None:
                    # if unparsable, include (best-effort)
                    rows2.append(r)
        rows = rows2
    if cb is not None:
        rows2 = []
        for r in rows:
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1] + "+00:00") if isinstance(ts, str) and ts.endswith("Z") else datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt is None or dt < cb:
                if dt is not None and dt < cb:
                    rows2.append(r)
                elif dt is None:
                    rows2.append(r)
        rows = rows2

    # sort newest-first
    def _key(r):
        ts = r.get("created_at")
        try:
            return datetime.datetime.fromisoformat(ts[:-1] + "+00:00") if isinstance(ts, str) and ts.endswith("Z") else datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    rows.sort(key=_key, reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    has_more = (offset + limit) < total
    next_cursor = _encode_cursor(offset + limit) if has_more else None

    # finalize audit invocation as succeeded and increment tenant usage (reads count)
    invs3 = _load("tool_invocations.json")
    for r in invs3:
        if r.get("id") == audit_id:
            r["status"] = "running"
            r["updated_at"] = now
            break
    _save("tool_invocations.json", invs3)

    tenants2 = _load("tenants.json")
    for t in tenants2:
        if t.get("id") == tenant_id:
            # quota counters increment on success
            t["monthly_request_used"] = int(t.get("monthly_request_used") or 0) + 1
            t["monthly_cost_usd_used"] = float(t.get("monthly_cost_usd_used") or 0.0)
            t["updated_at"] = now
            break
    _save("tenants.json", tenants2)

    invs4 = _load("tool_invocations.json")
    for r in invs4:
        if r.get("id") == audit_id:
            r["status"] = "succeeded"
            r["http_status"] = 200
            r["response_payload"] = {"total": total, "returned": len(page)}
            r["updated_at"] = now
            break
    _save("tool_invocations.json", invs4)

    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}, "invocation_id": audit_id}

