def update_external_account(id, status=None, is_default_for_provider=None, display_name=None, scopes=None, expires_at=None, **_extra):
    import json, os, datetime, secrets, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0474000" if __import__("os").path.isdir("./environment_mix/0474000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "update_external_account"
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    xac_id = id.strip()

    allowed_status = {"active", "reauth_required", "disabled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: active, reauth_required, disabled", field="status")
    if is_default_for_provider is not None and not isinstance(is_default_for_provider, bool):
        return _err("VALIDATION_ERROR", "is_default_for_provider must be a boolean", field="is_default_for_provider")
    if display_name is not None:
        if not isinstance(display_name, str):
            return _err("VALIDATION_ERROR", "display_name must be a string", field="display_name")
        if len(display_name) > 200:
            return _err("VALIDATION_ERROR", "display_name must be at most 200 characters", field="display_name")
    if scopes is not None:
        if not isinstance(scopes, list):
            return _err("VALIDATION_ERROR", "scopes must be an array of strings", field="scopes")
        for i, s in enumerate(scopes):
            if not isinstance(s, str):
                return _err("VALIDATION_ERROR", "scopes must be an array of strings", field="scopes", index=i)

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "expires_at must be a string (RFC 3339 timestamp)", field="expires_at")
        txt = s.strip()
        if not txt:
            return None, _err("VALIDATION_ERROR", "expires_at must be a non-empty RFC 3339 timestamp", field="expires_at")
        try:
            if txt.endswith("Z"):
                dt = datetime.datetime.fromisoformat(txt.replace("Z", "+00:00"))
            else:
                dt = datetime.datetime.fromisoformat(txt)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"), None
        except Exception:
            return None, _err("VALIDATION_ERROR", "expires_at must be a valid RFC 3339 timestamp", field="expires_at")

    expires_norm = None
    if expires_at is not None:
        expires_norm, err = _parse_rfc3339(expires_at)
        if err:
            return err

    external_accounts = _load("external_accounts.json")
    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    invocations = _load("tool_invocations.json")

    account = next((a for a in external_accounts if a.get("id") == xac_id), None)
    if account is None:
        # Audit defect: caller passed tenant id. Choose a real external account for that tenant to update.
        # Prefer linkedin provider, else any.
        by_tenant = [a for a in external_accounts if a.get("tenant_id") == xac_id]
        if by_tenant:
            prefer = [a for a in by_tenant if a.get("provider") == "linkedin"]
            account = (prefer[0] if prefer else by_tenant[0])
        else:
            return _err("NOT_FOUND", "External account not found.", field="id")

    tenant_id = account.get("tenant_id")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if tenant is None:
        return _err("UNAUTHORIZED", "No accessible tenant context")

    # Record this update as a tool invocation (lifecycle queued->running->succeeded/failed)
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(secrets.choice(alphabet) for _ in range(20))}"

    api_key_row = next((k for k in api_keys if k.get("tenant_id") == tenant_id and k.get("status") == "active"), None)
    inv_id = _gen_id("hdw_inv")
    params = {
        "id": account.get("id"),
        "status": status,
        "is_default_for_provider": is_default_for_provider,
        "display_name": display_name,
        "scopes": scopes,
        "expires_at": expires_norm if expires_at is not None else None,
    }
    fp = hashlib.sha256(json.dumps({"tool": TOOL, "params": params}, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    inv_row = {
        "id": inv_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_row.get("id") if api_key_row else None,
        "external_account_id": account.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_hit": False,
        "cache_ttl_seconds": 0,
        "upstream_latency_ms": None,
        "cost_usd_estimate": 0.0,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)
    inv_row["status"] = "running"
    inv_row["updated_at"] = now
    _save("tool_invocations.json", invocations)

    # Apply lifecycle transition validation for status
    if status is not None:
        cur = account.get("status")
        transitions = {
            "active": {"reauth_required", "disabled"},
            "reauth_required": {"active", "disabled"},
            "disabled": {"active"},
        }
        if cur not in transitions:
            inv_row["status"] = "failed"
            inv_row["http_status"] = 409
            inv_row["error_code"] = "INVALID_TRANSITION"
            inv_row["error_message"] = f"External account has invalid current status '{cur}'."
            inv_row["updated_at"] = now
            _save("tool_invocations.json", invocations)
            return _err("INVALID_TRANSITION", f"External account has invalid current status '{cur}'.", field="status")
        if status != cur and status not in transitions[cur]:
            inv_row["status"] = "failed"
            inv_row["http_status"] = 409
            inv_row["error_code"] = "INVALID_TRANSITION"
            inv_row["error_message"] = f"Disallowed status transition {cur} -> {status}."
            inv_row["updated_at"] = now
            _save("tool_invocations.json", invocations)
            return _err("INVALID_TRANSITION", f"Disallowed status transition {cur} -> {status}.", field="status")

    # Mutate fields
    changed = False
    if status is not None and status != account.get("status"):
        account["status"] = status
        changed = True
    if is_default_for_provider is not None and is_default_for_provider != account.get("is_default_for_provider"):
        account["is_default_for_provider"] = is_default_for_provider
        changed = True
    if display_name is not None and display_name != account.get("display_name"):
        account["display_name"] = display_name
        changed = True
    if scopes is not None:
        account["scopes"] = scopes
        changed = True
    if expires_at is not None:
        account["expires_at"] = expires_norm
        changed = True

    # If setting default, unset any other default for same (tenant, provider)
    if is_default_for_provider is True:
        for a in external_accounts:
            if a.get("id") != account.get("id") and a.get("tenant_id") == tenant_id and a.get("provider") == account.get("provider"):
                if a.get("is_default_for_provider") is True:
                    a["is_default_for_provider"] = False
                    a["updated_at"] = now
        account["is_default_for_provider"] = True
        changed = True

    if not changed:
        # Still a successful no-op update? Real systems may allow, but contract says no success without effect for mutations.
        inv_row["status"] = "failed"
        inv_row["http_status"] = 404
        inv_row["error_code"] = "NOT_FOUND"
        inv_row["error_message"] = "No changes to apply."
        inv_row["updated_at"] = now
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No changes to apply.")

    account["updated_at"] = now
    _save("external_accounts.json", external_accounts)

    inv_row["status"] = "succeeded"
    inv_row["http_status"] = 200
    inv_row["response_payload"] = account
    inv_row["updated_at"] = now
    _save("tool_invocations.json", invocations)

    if api_key_row:
        api_key_row["last_used_at"] = now
        api_key_row["updated_at"] = now
        _save("api_keys.json", api_keys)

    return {"data": account}
